      "content": "{\n  \"name\": \"@oh-story/dsh\",\n  \"version\": \"0.1.21\",\n  \"description\": \"A DSH plugin for fiction, short-drama, interactive-game, and video-recap production\",\n  \"keywords\": [\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"oh-story\",\n    \"drama-skills\",\n    \"novel-to-game\",\n    \"creative-writing\",\n    \"fiction-writing\",\n    \"novel-writing\",\n    \"short-drama\",\n    \"screenwriting\",\n    \"interactive-fiction\",\n    \"game-development\",\n    \"video-recap\",\n    \"video-production\",\n    \"ai-agents\"\n  ],\n  \"homepage\": \"https://github.com/zenstory-ai/oh-story-dsh#readme\",\n  \"bugs\": \"https://github.com/zenstory-ai/oh-story-dsh/issues\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/zenstory-ai/oh-story-dsh.git\",\n    \"directory\": \"packages/dsh-plugin\"\n  },\n  \"publishConfig\": {\n    \"access\": \"public\",\n    \"provenance\": true\n  },\n  \"engines\": {\n    \"node\": \">=24.0.0\",\n    \"dsh\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\"\n  },\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"types\": \"./lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-store\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-tool\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"files\": [\n    \"cordis.patch.yml\",\n    \"lib/**/*\",\n    \"LICENSE\",\n    \"README.md\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsx ../../scripts/build-dsh-plugin.ts && tsc -p tsconfig.build.json\",\n    \"prepack\": \"pnpm build\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\",\n    \"test\": \"vitest run\",\n    \"test:contract\": \"vitest run contract\"\n  },\n  \"license\": \"MIT\",\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"^4.0.4 || ^4.0.5-alpha.1 || ^4.0.6-alpha.1\",\n    \"@deepseek-ai/dsh-agent\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-api-session-controller\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-store\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-session\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-client-ui-tool\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-fs\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-host-webserver\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-llm\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-session\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-skill\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-subagent\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-tools\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-typert-registry\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/dsh-util-values\": \">=0.2.0-rc.2 <0.2.1-0 || >=0.2.1-alpha.1 <0.2.2-0 || >=0.2.2-alpha.2 <0.2.3-0\",\n    \"@deepseek-ai/schemastery\": \"^3.18.4 || ^3.18.5-alpha.1 || ^3.18.6-alpha.1\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"zod\": \"^4.4.3\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.5\",\n    \"@deepseek-ai/dsh-agent\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-api-session-controller\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-store\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-chat\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-conversation\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-renderer\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-session\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-client-ui-tool\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-fs\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-llm\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-session\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-sandbox-policy\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-skill\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-subagent\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-tools\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-typert-registry\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/dsh-util-values\": \"0.2.1-rc.5\",\n    \"@deepseek-ai/schemastery\": \"3.18.5\",\n    \"@types/react\": \"18.3.28\",\n    \"@types/react-dom\": \"18.3.7\",\n    \"react\": \"18.3.1\",\n    \"react-dom\": \"18.3.1\",\n    \"typescript\": \"6.0.3\",\n    \"zod\": \"4.4.3\"\n  }\n}\n"
