      "path": "packages/dsh-plugin/src/index.ts",
      "content": "import type { Context } from \"@deepseek-ai/cordis\";\nimport type {} from \"@deepseek-ai/dsh-host-webserver\";\nimport type {} from \"@deepseek-ai/dsh-skill\";\nimport type {} from \"@deepseek-ai/dsh-subagent\";\nimport type {} from \"@deepseek-ai/dsh-tools\";\nimport z from \"@deepseek-ai/schemastery\";\nimport { createDramaSkillProvider, createNovelToGameSkillProvider, createOhStorySkillProvider, createVideoRecapSkillProvider, defaultDramaSkillRoot } from \"./skill-provider.js\";\nimport { ensureDramaAdapterConfig } from \"./drama-adapters.js\";\nimport { DRAMA_PYTHON, hostPython } from \"./host-python.js\";\nimport { registerOhStoryHooks } from \"./native-hooks.js\";\nimport { registerOhStoryRoleTool } from \"./role-tool.js\";\nimport { registerOhStoryProductionTool } from \"./production-tool.js\";\nimport { registerWorkspaceRoute } from \"./workspace-route.js\";\nimport { assertTrustedWorkspaceAuthority } from \"./workspace-request-trust.js\";\n\nexport { createDramaSkillProvider, createNovelToGameSkillProvider, createOhStorySkillProvider, createVideoRecapSkillProvider, parseBundledSkill } from \"./skill-provider.js\";\nexport { OH_STORY_ROLE_NAMES, loadBundledRole } from \"./role-provider.js\";\nexport { createOhStoryRoleTool, OH_STORY_ROLE_TOOL_NAME, registerOhStoryRoleTool, roleToolFilter, type OhStoryRoleSubagents } from \"./role-tool.js\";\nexport { createOhStoryProductionTool, registerOhStoryProductionTool } from \"./production-tool.js\";\nexport { OH_STORY_PRODUCTION_TOOL_NAME, validateProductionIntent, type ProductionIntentArgs } from \"./production-intent.js\";\nexport { bundledReferenceGuard, createOhStoryReferenceTool, OH_STORY_REFERENCE_TOOL_NAME } from \"./reference-tool.js\";\nexport { registerWorkspaceRoute } from \"./workspace-route.js\";\nexport { registerOhStoryHooks } from \"./native-hooks.js\";\nexport { DRAMA_ADAPTER_CONFIG_ENV, DRAMA_ADAPTERS, dramaAdapterConfigPath, dramaAdapterStatuses, ensureDramaAdapterConfig } from \"./drama-adapters.js\";\n\nexport const name = \"oh-story\";\nexport const inject = [\"skills\", \"subagents\", \"tools\", \"typert\", \"webServer\"];\n\n/** DSH owns models, providers, presets, permissions, roots, runs, and sessions. */\nexport interface Config {\n  readonly editorMaxBytes?: number;\n  readonly trustedHosts?: string[];\n}\n\nexport const Config = z.object({\n  editorMaxBytes: z.natural().min(65_536).max(8_388_608).default(2_097_152),\n  trustedHosts: z.array(String).default([])\n}) as z<Config>;\n\n/** Mount only domain contributions into the current DSH process. */\nexport async function apply(context: Context, config: Config = {}): Promise<void> {\n  const trustedHosts = config.trustedHosts ?? [];\n  for (const entry of trustedHosts) assertTrustedWorkspaceAuthority(entry);\n  context.skills.registerProvider(() => createOhStorySkillProvider());\n  context.skills.registerProvider(() => createDramaSkillProvider());\n  context.skills.registerProvider(() => createNovelToGameSkillProvider());\n  context.skills.registerProvider(() => createVideoRecapSkillProvider());\n  registerOhStoryHooks(context);\n  registerOhStoryProductionTool(context);\n  await registerOhStoryRoleTool(context);\n  registerWorkspaceRoute(context, { maxBytes: config.editorMaxBytes ?? 2_097_152, trustedHosts });\n  // Register the bundled media adapters for this host up front so the first\n  // short-drama-produce run has a config to pass; the preflight route repeats\n  // this and reports the outcome, so a failure here only delays the message.\n  await ensureDramaAdapterConfig(defaultDramaSkillRoot(), { python: (await hostPython(DRAMA_PYTHON)).command });\n}\n\nexport default { name, inject, Config, apply };\n"
    },
    {
      "path": "packages/dsh-plugin/src/skill-provider.ts",
      "content": "import { readdir, readFile } from \"node:fs/promises\";\nimport { basename, dirname, isAbsolute, join, relative, resolve } from \"node:path\";\nimport { dramaAdapterConfigPath, dramaAdapterSummary, DRAMA_ADAPTER_CONFIG_ENV } from \"./drama-adapters.js\";\nimport { fileURLToPath, pathToFileURL } from \"node:url\";\nimport {\n  BUNDLED_SKILL_RANK,\n  type SkillCandidate,\n  type SkillDefinition,\n  type SkillProvider\n} from \"@deepseek-ai/dsh-skill\";\n\nconst STORY_PROVIDER_NAME = \"oh-story\";\nconst DRAMA_PROVIDER_NAME = \"short-drama\";\nconst GAME_PROVIDER_NAME = \"novel-to-game\";\nconst VIDEO_PROVIDER_NAME = \"video-recap\";\nconst DSH_SKILL_BRIDGE = [\n  \"<oh-story-dsh-integration>\",\n  \"This Skill is a native contribution to the current DeepSeek Harness session.\",\n  \"DSH owns the workspace, model, preset, permissions, Session Log, tools, subagents, cancellation, resume, and Agent UI.\",\n  \"Never start another Agent runtime, session transport, Dashboard, SSE stream, polling loop, or model configuration.\",\n  \"All seven upstream Oh Story specialist Roles are bundled. Invoke one with oh_story_role and a self-contained prompt.\",\n  \"Never inspect .claude/agents, .codex/agents, .opencode/agents, .agents/agents, .zcode, or .story-deployed to decide whether a Role is available.\",\n  \"Oh Story Roles are reached only through oh_story_role. Never start one through a generic subagent or Task tool — not DSH's subagent or subagent_fork tools, not invoke_subagent, and not an Agent tool — and never pass a Role name as subagent_type, agent_type, agent, or TypeName, even where the upstream text below describes that for another host.\",\n  \"Use only DSH-visible tools. DSH sandbox and permission policy remain authoritative.\",\n  // Upstream deploys these 「与作者协作」 rules only in its CLAUDE.md/AGENTS.md\n  // templates, which DSH does not install.\n  \"Working with the author: reply in the language the author writes in, and keep progress updates in that language while you wait for oh_story_role or any other background helper to return; reply and report in the author's writing terms (book, chapter, outline, settings), never in script, field, or state names; attach a raw error only when something failed. A template block marked <!-- author-report --> is only a format reference: output its text directly, without that marker and without a code fence.\",\n  \"Manage a writing habit or preference only through story-long-write or story-short-write and that writing Skill's references/author-memory.md and scripts/author_memory_commit.py; never keep it in a host or DSH memory. The story entry only routes memory requests. story-deslop and story-review consume only preferences already supplied by their caller and never query or record author memory themselves. Simply follow a one-off request without recording it.\",\n  \"Never edit the bundled Skill files (SKILL.md, references/, scripts/). When a Skill script fails, stop and show the author the command you ran and its error instead of patching or working around it.\",\n  \"</oh-story-dsh-integration>\"\n].join(\"\\n\");\n/** Oh Story 0.8.4 long-form analysis Stage 2 (pipeline-ops.md §4), shared by story-long-analyze and story-import. */\nconst DSH_ANALYSIS_BATCHES = [\n  \"Stage 2 batches in DSH: dispatch each planned batch with oh_story_role, role chapter-extractor, and a self-contained prompt that copies this batch's plan fields verbatim, prefixing paths with {拆文目录}/: batch_id, input_kind, source_files (per-chapter source_locator for a raw batch), chapter_chars, min_plot_points, the output file {拆文目录}/_analysis_cache/输入-{批次ID}.md, and the plan's handoff_cache when it is not empty.\",\n  \"The extractor reads the source itself, writes or edits only that batch input file (DSH denies any other write or edit by a chapter-extractor child), and replies with one receipt line; do not read the file yourself.\",\n  \"Commit it with manage_analysis_run.py commit, one commit at a time in this session. When a commit is rejected, dispatch the same batch to a chapter-extractor again with every field above plus the error code, and have it fix only the broken spots with edit (rewriting the whole file only when its structure is broken), then commit again.\",\n  \"Run manage_analysis_run.py and the other bundled Python 3 scripts through the current DSH execution world, trying python3, python, then py -3. If none is available, stop and tell the author in plain words that this step needs Python 3 on the machine running DSH; never simulate a script's output or hand-write the files it owns.\",\n  \"Keep concurrent oh_story_role calls modest. The default is upstream's 有限并行 tier: three batches per round, issued together, the next round only after all three are committed; an unasked, full, multi-book, or import run uses it. DSH runs calls from one step in parallel only up to the host's own limit and may run them one after another, so never promise more. Use 串行 or 不限批次顺序 only when the author chooses it, and under 不限批次顺序 halve the count on any rate limit, timeout, or child error.\"\n].join(\" \");\nconst DSH_AUTHOR_MEMORY_WORKSPACE = \"For author memory in DSH's usual single-book layout, where 正文/ and 设定/ sit directly in the workspace root, pass that same root as both --workspace and --book-root; the book store lives at .story/作者记忆/书级/. For a book in a subdirectory, --book-root names that book's directory. Keep --workspace explicit, pass --book-root on every command for a book, and include --kind on queries. Use this writing Skill's references/author-memory-maintenance.md for single-book layout recovery, organizing memories, or migrating old 本书： entries.\";\nconst DSH_SKILL_OVERRIDES: Readonly<Partial<Record<string, string>>> = {\n  story: \"The 小说 workspace is an official DSH conversation view. Never start or open a second web application.\",\n  \"story-setup\": \"Initialize or validate novel project data only. DSH already supplies Skills, Roles, hooks, tools, permissions, sessions, and UI; never deploy Claude/OpenCode/Codex/Antigravity/ZCode/OpenClaw/Reasonix files or a .story-deployed marker.\",\n  \"story-long-analyze\": `Use oh_story_role for chapter extraction or specialist analysis. Never inspect platform agent directories or require a deployed external Agent definition. ${DSH_ANALYSIS_BATCHES}`,\n  \"story-long-write\": `All named Roles are provided through oh_story_role. Do not check platform agent files. Keep the upstream writing, Tracking, lint, outline, revision, and quality workflows. Create and assemble 正文/ chapter files only with the write and edit tools, never through shell redirection, cp, mv, tee, or a script, so that DSH's outline guard, its Tracking reminder, and the 小说 view observe the write; upstream's own in-place chapter fixes such as storyctl.py chapter check --fix-punctuation stay as upstream describes. ${DSH_AUTHOR_MEMORY_WORKSPACE}`,\n  \"story-review\": \"All named reviewer Roles are provided through oh_story_role. Do not check platform agent files; full/lean review may use the bundled Roles directly. When a review falls back to solo in DSH, the reason is that oh_story_role or DSH's spawn runtime is unavailable in this Session (Fallback agent tool unavailable -> solo) or a Role run failed (Fallback spawn failed -> solo); say that in one plain sentence. Never tell the author that the reviewers are not installed, missing, or outdated, and never tell them to run /story-setup.\",\n  \"story-import\": `All named Roles are provided through oh_story_role. Do not require story-setup to deploy them, never inspect platform agent directories or .story-deployed, and never offer the author Step 4's choice to install a writing environment with /story-setup: in DSH record 写作环境 in .story/work/导入记录.md as installed, with the analysis helper and story-architect both available. Phase 2 runs the story-long-analyze pipeline the DSH way below; an import counts as automatic continuation, so it uses the limited-parallel tier without asking. ${DSH_ANALYSIS_BATCHES} Run the scripts this Skill needs (build_outline_brief.py, outline_view.py --check --strict, tracking_commit.py init and check with Python 3; check-outline-contract.js with Node) the same way. Keep upstream's order: in the long-form structure migration (references/structure-mapping-long.md) Step 2 copies the manuscript into 正文/, Step 10 reverse-builds the 细纲 in batches, and Phase 4 initialises Tracking. After the import, tell the author to continue a long book with /story-long-write 写第N章 (N is the next chapter after the imported ones) and a short story with /story-short-write by asking it to 补完构思. DSH's prose guard mirrors the outline gate of upstream proseBlockReason for books with 大纲/ or 追踪/, so open an import window before Step 2 copies any chapter: create .story/work/导入中.md in the book directory (the workspace root in DSH's usual single-book layout) with one line naming the book being imported, and delete it right after Phase 4's tracking_commit.py init and check both succeed. The window only holds while 追踪/_tracking-state.json is absent. 导入中.md is DSH's own marker; keep upstream's 导入记录.md exactly as the Skill describes.`,\n  \"story-deslop\": \"Use the bundled narrative-writer Role through oh_story_role when specialist review is useful. Never inspect platform agent directories.\",\n  \"story-short-analyze\": \"Use oh_story_role for specialist analysis. Never inspect platform agent directories or require external Agent deployment.\",\n  \"story-short-write\": `All named Roles are provided through oh_story_role. Do not inspect platform agent files; preserve the upstream short-fiction workflow and quality gates. ${DSH_AUTHOR_MEMORY_WORKSPACE}`,\n  \"browser-cdp\": \"Use only browser or web capabilities visible in the current DSH preset. Do not start a parallel browser host; if no compatible capability is visible, explain the limitation.\",\n  \"story-cover\": \"Use only image-generation or HTTP capabilities visible in the current DSH preset. Never assume a separate Codex or Claude runtime. When no such capability is visible, offer the upstream prompt-only mode instead of a paid API.\",\n  \"story-publish\": \"Prepare the listing file only. Never sign in to, fill in, or submit anything on a platform's author backend, even when a browser tool is visible in the current DSH preset; hand the author the saved 发布资料 file instead.\"\n};\nconst DSH_DRAMA_BRIDGE = [\n  \"<short-drama-dsh-integration>\",\n  \"This Skill is a native contribution to the current DeepSeek Harness session.\",\n  \"DSH owns the workspace, model, preset, permissions, Session Log, tools, approvals, cancellation, resume, and Agent UI.\",\n  \"The 短剧 tab is the creator workspace. Never start dashboard_server.py, another web server, Dashboard, Agent runtime, session transport, or model configuration.\",\n  \"Drama Skills uses a creator-first contract: each episode keeps only the requested documents, up to five creator-facing sources at 剧集/<EP>/剧本.md, 视觉设定.md, 分镜.md, 图片提示词.md, and 视频提示词.md. Never precreate empty documents, backfill nominal stages, or start work the creator did not request. Persisted reviews use creator-readable Markdown under 审查/; an oral review writes nothing.\",\n  \"剧集/<EP>/剪辑单.md is the v0.7 assembly record, not a sixth creative truth: the five creator documents stay the creative truth. It is written after readable media exists and records what reaches the cut — which footage or accepted static keyframes are kept or left unused and why, each cut's in/out timing, its subtitles, 画面文字 overlays, 音效 cues, 配音 and 环境声, post-processing such as shot-match correction or an external mix, and the delivery spec including optional 颗粒 grain and 接镜匹配. It never changes a line, a shot's job, or a declared duration; changing any of those means returning to the document that owns it.\",\n  \"For a v0.6 project, never create a parallel JSON/JSONL lifecycle truth, indexes, fingerprints, coverage tables, or QA records; Drama 0.9.1 no longer bundles the legacy JSON checkers, and creator_markdown_check.py is the structural check.\",\n  \"Never upgrade a v0.5 structured project in place or mix both contracts in one project root. Keep legacy production/audit artifacts read-only and pinned to v0.5; migrate only into a new creator-first root with manual per-episode creator confirmation.\",\n  \"Use only tools visible in the current DSH preset and preserve the upstream project ownership, freshness, review, and explicit production-confirmation contracts.\",\n  \"Use oh_story_production only for semantic production-view intents (open/focus, explicit shot order, or tracking a job that this Agent is actually executing). Cosmetic canvas layout remains creator-controlled. The tool changes only the Session projection: it does not edit creator documents, generate media, or authorize production.\",\n  \"Production credentials remain outside project files. Never treat a prior acceptance, preview, continuation request, or budget discussion as confirmation for a paid production run.\",\n  \"</short-drama-dsh-integration>\"\n].join(\"\\n\");\nconst DSH_DRAMA_OVERRIDES: Readonly<Partial<Record<string, string | ((skillRoot: string) => string)>>> = {\n  \"short-drama\": \"A dashboard request means focus or use the native 短剧 tab in this DSH Session. Do not run the bundled standalone Dashboard script. New projects follow only the v0.6 creator-first contract and create only documents required by the current request.\",\n  \"short-drama-produce\": (skillRoot) => `Use an upstream adapter only after the creator explicitly confirms the exact current job. Its source must be the current creator-first Markdown and its output belongs under 剧集/<EP>/制作成果/. DSH permissions and approval UI remain authoritative. When oh_story_production is visible, register a previewed image or video job with track_job after the confirmation is valid and before run — never at prepare time — passing the same job ID, target, modality and count the creator just approved. track_job's jobKind is image, video or composition (the assembled cut), so from this Skill it registers image and video jobs only: speech (tts) and music jobs pass through the same prepare → explicit creator confirmation → run gate but are never registered with track_job or relabelled as another kind, and their audio results stay under 剧集/<EP>/制作成果/. Optional voice references belong on the MOTION entry's separate 参考音频 line, never in 输入参考图 or the workbench image picker. Compile them as reference_audio bindings, preserve character exactly from 角色, and match the project-local audio path to that character's single 声音参考 in 视觉设定.md. 不得控制 lists 台词、语气、情绪 individually. The selected adapter profile must explicitly declare reference_audio in reference_roles; otherwise reject before paid submission, never drop or substitute the binding. The generated generic adapter profiles intentionally omit reference_audio because their model IDs are environment-selected; use a creator-owned OH_STORY_DRAMA_ADAPTER_CONFIG profile that declares audio support only for a known reference-audio-capable model. DeepSeek generates no media: every image, video, speech, or music result comes from a provider adapter. The bundled adapters are ${dramaAdapterSummary()}; they are registered for this DSH host in ${dramaAdapterConfigPath(skillRoot).path} — pass that file as --adapter-config unless the creator names another config (${DRAMA_ADAPTER_CONFIG_ENV}). Credentials are read only from the DSH host process environment. Before preparing a paid job, name the adapter that will run it; if its variables are missing, tell the creator exactly which ones to export before starting DSH instead of failing inside run. Never read, print, or write credential values. A submitted video job is already billed, so an interrupted run is recovered, not resubmitted: when audit reports orphaned_provider_job, recover it with collect, passing --job-id — the drama job the finding names, not its provider_job_id, which collect reads from the run handle itself. collect spends nothing and does not need the confirmation gate — the gate exists to stop unintended spending — but re-running the same job does, and would charge the creator twice.`,\n  \"short-drama-edit\": [\n    \"Assembly runs inside this DSH Session. Write 剧集/<EP>/剪辑单.md first, then run edit_tool.py check and render through the current DSH execution world; the rendered cut belongs under 剧集/<EP>/制作成果/成片/ and the 短剧 tab shows it there. ffmpeg and ffprobe come from the DSH host — when one is missing, say so instead of approximating or reporting an untested measurement as a pass.\",\n    // edit_tool.py 0.7.1 `_unaccounted_shots`: `- 未采用镜头：` is read only outside CUT blocks, split on `；`, and each item must fullmatch `MOTION-…（理由：<non-empty>）`.\n    \"Video cuts use existing MOTION IDs; static-frame cuts use SHOT IDs from 分镜.md or IMG IDs from 图片提示词.md and accepted png/jpg/jpeg/webp files. Every unused MOTION and, when static cuts exist, every storyboard SHOT must be accounted for before the first `## CUT-` on one line: `- 未采用镜头：MOTION-…（理由：…）；SHOT-…（理由：…）`. Join items with a full-width `；`; reasons name 文件缺失, 质量不可用 or 叙事取舍. A static CUT starts at 0.00, lasts at least 0.50 seconds, requires the delivery width/height/frame rate, and may use 运镜. The native production sequence accepts video and accepted keyframe images, keeps storyboard order and source identity, and dispatches /short-drama-edit in Chat; never relabel images as video or generate paid video unnecessarily.\",\n    \"Every video cut must share one width, height and frame rate: render hard-joins the encoded video segments and never scales or retimes them. Static cuts are rendered to the delivery specification with the declared crop/motion. When check reports a mismatch, normalise the odd clips to the delivery spec with ffmpeg in the DSH execution world, under approval, preserving the composition. Write them under 剧集/<EP>/制作成果/成片/规格统一/, an edit-owned intermediate, never beside the produce-stage originals and never over produced footage, and name them without the original's job-id token (the MOTION ID will do). Record the crop or pad in that CUT's block (not in its 画面 line, which accepts only 亮度/饱和/色温), point 来源 at the new file, update 入点/出点 if the conversion moved them, and rerun check.\",\n    \"The default burned-subtitle route needs an ffmpeg built with libass; when the host's ffmpeg lacks it, say so instead of silently dropping subtitles. Remotion renders every frame through a headless browser from a Node workspace outside the project, ~/.cache/short-drama-edit/remotion, which edit_tool.py rewrites on each run: the optional subtitle route uses it, and any `画面文字` line in 剪辑单.md requires it whatever the subtitle route. Install it (npm install in that workspace; an install from before Drama Skills 0.8 must run npm install again) only after the creator approves, through DSH approval. Without that approval write no 画面文字 lines and tell the creator the blank on-screen panels stay empty. Never treat Remotion as a second Agent runtime, dashboard, or session transport.\",\n    \"The 声音 line in 剪辑单.md is a record, not an instruction the built-in render executes. render trims, auto-matches adjacent cuts within one scene (a CUT's 画面 correction replaces it, `- 画面：不校` skips it, and `- 接镜匹配：无` in the delivery spec turns it off), hard-joins, mixes in the `音效` lines, cross-cut `配音` and looping `环境声`, burns subtitles and 画面文字, applies optional 颗粒, and normalises loudness. A mix beyond the declared 音效/配音/环境声 lines, crossfade, transition or format conversion is an external ffmpeg step, run under approval, that writes a temporary file, ends as render does with whole-film two-pass loudnorm to the declared 交付响度 (I=<交付响度>:TP=-1.5:LRA=11, the second pass fed the first pass's measurements with linear=true, audio re-encoded as AAC 192k at 48 kHz), and only then replaces 剧集/<EP>/制作成果/成片/成片.mp4; record its command in 剪辑单.md and repeat it after any re-render, which overwrites that file. Run edit_tool.py verify last, on that delivered file, and report every 未测 item as untested, never as passed.\",\n    \"This stage never generates footage and never edits 剧本.md, 分镜.md, or 视频提示词.md — route those back to their owning Skill.\"\n  ].join(\" \"),\n  \"short-drama-assets\": \"Keep one stable `- ID：VISUAL-*` line on every 人物/造型/地点/道具/状态 entry in 视觉设定.md, and never change an existing ID when editing its heading or text. The 生产 view identifies canvas nodes by that ID; entries without one still render, but the workbench reports their node identity as unstable.\"\n};\nconst DSH_GAME_BRIDGE = [\n  \"<novel-to-game-dsh-integration>\",\n  \"This Skill is a native contribution to the current DeepSeek Harness session.\",\n  \"DSH owns the workspace, model, preset, permissions, Session Log, tools, approvals, cancellation, resume, Todo, and Chat UI.\",\n  \"The 游戏 tab is the playable Game Studio. Never start a second Agent runtime, dashboard, session transport, or model configuration.\",\n  \"Keep the complete upstream seven-Skill pipeline and write adaptation artifacts under game-adaptations/<project>/ exactly as the upstream contracts specify.\",\n  \"For a web target, keep the authoritative playable entry at build/app/index.html so Game Studio can preview it. Do not silently replace a requested non-web runtime with a web build.\",\n  \"The first time build/app/index.html becomes playable, tell the user in one sentence that they can already play it in the 游戏 tab and what work remains, then continue; keep the Todo list in step with the pipeline stage.\",\n  \"Use only DSH-visible tools and approvals. qa/verification.json remains the sole machine QA truth and must cover launch, render, input, coreLoop, outcome, and restart with real execution evidence.\",\n  // NovelToGame 0.6.0 pipeline-contract.md: with no target player available, the whitebox playtest uses a fresh agent that has not read the design or source.\n  \"When the whitebox playtest calls for a fresh agent that has not read the design documents or source, run it as a DSH subagent visible in this preset, giving it only the playable entry and normal player input; in director mode, ask the user in this Session first whether a real target player can try it.\",\n  \"The bundled Jin Ping Mei project is a read-only example, not a template to copy mechanically and not proof that another adaptation passed QA.\",\n  \"</novel-to-game-dsh-integration>\"\n].join(\"\\n\");\nconst DSH_VIDEO_BRIDGE = [\n  \"<video-recap-dsh-integration>\",\n  \"This Skill is a native contribution to the current DeepSeek Harness session.\",\n  \"DSH owns the workspace, model, preset, permissions, Session Log, tools, approvals, cancellation, resume, Todo, Chat, and the 视频 preview Studio.\",\n  \"Never start a second Agent runtime, dashboard, session transport, web server, polling loop, or model configuration.\",\n  \"A dashboard request means the native 视频 tab in this DSH Session: dashboard_server.py and its dashboard assets are not bundled, so never try to run them. To inspect a resource library, use the read-only scripts/library.py check, list, or show.\",\n  \"Keep the complete upstream six-Skill production pipeline plus the on-demand video-reference Skill; video-reference extracts reusable production references only when requested and never enters the default production path. Put each project under video-recaps/<project>/, copy or import source media under sources/, and use work/ as the upstream work_dir so the Studio can discover authoritative manifests and outputs. A project binding passed with --project belongs at video-recaps/<project>/recap_project.json.\",\n  \"full-mode validation is lint-only: never truncate, drop, merge or reorder approved narration to satisfy a budget; report over_budget and request a revised script. final_qc.json uses schema 2 findings (code/message/blocking/evidence/next_action); do not read removed golden_eval.json, mimo_qc.json or preflight_qc.json. Do not pass removed --mimo-qc, --preserve-approved-text or --clip-padding flags, MIMO_QC* variables, CLIP_PADDING or SOURCE_VIDEO. Except dub, delivery uses tagged H.264 8-bit 4:2:0 with true peak <= -1 dBTP; delivered_true_peak_over_target blocks delivery. If libass is unavailable, deliver external .srt rather than dropping subtitles or aborting preflight.\",\n  \"The Video Studio is a preview and artifact surface, not a nonlinear editor. Do not invent a second project-state format, timeline truth, or render queue; recap_run_manifest.json, recap_phase.json, timeline.json, assembly_manifest.json, and the upstream artifacts remain authoritative.\",\n  \"--edit-mode dub sends the source audio to MiMo ASR and clones the original speaker's voice, so it requires --confirm-voice-rights. Ask the user first and pass it only after they confirm they may use the video's audio and the speaker consents to voice cloning; never add it on your own, including to resume commands printed for an older work_dir.\",\n  \"MIMO_API_KEY, FISH_API_KEY, and voice credentials stay in the host environment. Never write secrets into project files, tool arguments shown to the browser, or chat output.\",\n  \"Use only DSH-visible tools and approvals. Run Python and ffmpeg through the current DSH execution world, preserve cancellation, and do not install or upgrade system dependencies without explicit user approval.\",\n  \"When a new edited or final video is ready, tell the user that Video Studio can load it; never interrupt playback by replacing the currently loaded video silently.\",\n  \"</video-recap-dsh-integration>\"\n].join(\"\\n\");\n\nconst DSH_NATIVE_SKILLS: Readonly<Partial<Record<string, string>>> = {\n  story: `# story — DSH 小说流程入口\n\n在当前 DSH Session 内判断用户意图，并加载最匹配的 Oh Story Skill：\n\n- 新建或修复小说工程：story-setup\n- 长篇规划与写作（讨论长篇结构、规划剧情、开书、写大纲、补细纲、写正文、日更）：\n  story-long-write。只要结构、大纲、卷纲或细纲时只交付所请求的规划，不写正文；\n  用户明确要求写正文才进入正文流程\n- 长篇选题/扫榜：story-long-scan；长篇拆文：story-long-analyze。只说「选题」「看看写什么」\n  又没说篇幅时，先问一句长篇还是短篇\n- 灵感库、提炼灵感、跨书灵感聚合、更新灵感库：story-long-analyze 的可选灵感库管道\n  （单书拆文不自动入库）\n- 短篇选题/拆文/写作：story-short-scan、story-short-analyze、story-short-write\n- 导入已有作品：story-import。导完长篇说 /story-long-write 写第N章（N 是导入后的下一章）\n  续写；导完短篇用 /story-short-write 补完构思\n- 审稿与去 AI 味：story-review、story-deslop\n- 封面：story-cover（只要封面提示词、不生图时也走它）\n- 整理平台建书资料（发布资料、建书表单、平台书名/简介/标签）：story-publish；只说「开书」\n  照常进 story-long-write\n- 查本书的角色、伏笔、进度或设定：用 oh_story_role 调用 story-explorer；查外部资料：\n  story-researcher。助手返回的英文字段和缺口说明由你翻成白话再说；回答讲故事里的事，\n  编号只跟着故事描述出现\n- 管理作者习惯（记住/查看/确认/替换/忘掉写作偏好）：按作者指定的长篇/短篇类型，\n  加载 story-long-write 或 story-short-write，由对应写作 skill 管理；未指定时按下方\n  「当前书」的篇幅选择。无当前书的\n  通用习惯默认交 story-long-write；只限定本书却无法定位时问哪本书，不要求先建书。\n  路由层不读写作者记忆文件。仅管理习惯时完成即停，不建书、不写正文。\n\n当前书：项目根有 .active-book 且指向项目内存在的目录就是它（DSH 常见的单书布局里，\n工作区根本身就是书目录）；否则从工作区根往下最多 4 层找，跳过以 . 开头的目录、\nnode_modules、拆文库/、对标/，含 追踪/、正文/ 子目录或 正文.md 文件、含\n设定/题材定位.md、或同时有 设定.md 与 小节大纲.md 的目录都算书。找到多本又没有\n.active-book 时问作者是哪本，选定后把相对路径写进项目根 .active-book。篇幅：有 正文/\n或 设定/ 子目录的是长篇，有 正文.md 或 设定.md 文件的是短篇。审稿和封面按同一规则找书。\n\n只说 /story、看不出意图时，不贴路由表，给四个白话选项：「开一本长篇或接着写」→\nstory-long-write；「写一篇短篇」→ story-short-write；「把一章改得不那么 AI」→\nstory-deslop；「更多（拆书、扫榜、导入旧稿、审稿、封面、发布资料）」→ 再列进阶项。意图明确时\n直接进入对应 Skill；只差一个会改变流程的选择时只问这一个问题。项目文件、Agent、\n模型、权限、Session Log 和 UI 均由当前 DSH 会话管理。小说文件通过“小说”视图查看，\nAgent 过程通过右侧动态栏或官方 Chat 查看。禁止启动独立 Dashboard。`,\n  \"story-setup\": `# story-setup — DSH 原生小说工程初始化\n\n只初始化或校验当前 DSH workspace 中的小说数据，不部署任何 Agent 平台文件。\n\n1. 检查现有正文、设定、大纲和追踪文件，已有内容绝不覆盖。\n2. 根据用户声明与现有结构判断长篇/短篇：有 正文/ 或 设定/ 子目录的是长篇，有 正文.md\n   或 设定.md 文件的是短篇；无法可靠判断时请求确认。\n3. 长篇按需建立 正文/、设定/、大纲/。初始化、开书、大纲和细纲阶段都不建 追踪/，\n   也不写 追踪/_tracking-state.json：追踪在第一章正文动笔前，由 story-long-write\n   单章流程用它的 scripts/tracking_commit.py init 初始化（事务 JSON 放书目录\n   .story/work/，check 通过后删掉），之后每章由脚本提交。_tracking-state.json 与\n   上下文.md 等派生 Tracking 视图只由脚本生成，绝不手改。\n   第一章正文落盘前必须有对应细纲。短篇保持轻量结构，不强加长篇 Tracking。\n4. 已有正文却没有 追踪/_tracking-state.json 时，不自行补建追踪文件：已有旧 追踪/\n   的是旧追踪结构，建议走 story-import 的「旧追踪项目迁移」；没有 追踪/ 的既有书稿\n   建议用 story-import 导入。\n5. 需要架构、角色或研究工作时，通过 oh_story_role 调用已打包 Role；不要检查或\n   生成 .claude、.codex、.opencode、.agents、.zcode、AGENTS.md 或 .story-deployed。\n6. 给作者的报告按这个顺序写：先写「现在可以做什么」，用写书的话列真正可用的事\n   （如「可以开新书、续写：说 /story-long-write」）；再写「你还需要做的事」，逐条\n   可照做（含需要作者确认的长篇/短篇判断），没有就写「无需其他操作」。这两段不出现\n   脚本名、字段名、状态名或文件路径；最后才简短列出创建和保留了哪些文件。\n   不要配置模型、权限、Hooks 或 Session。\n\n题材、角色、节奏、冲突、开篇和写作方法资料位于 references/agent-references/；\n只加载当前任务需要的文件。`,\n  \"browser-cdp\": `# browser-cdp — DSH 浏览器能力适配\n\n本 Skill 不启动 Chrome、CDP 端口、独立浏览器 Host 或 setup-cdp-chrome.js。\n仅使用当前 DSH Preset 已暴露的 web_search、web_fetch 或浏览器工具完成网页读取、\n榜单采集和资料核验。保持以下原则：\n\n1. 优先使用结构化搜索/抓取工具；需要登录态或交互页面时才使用可见浏览器能力。\n2. 尊重站点条款、访问频率与用户授权；不绕过验证码、付费墙或访问控制。\n3. 记录来源 URL、采集时间、失败项和数据质量，不把推断写成页面事实。\n4. 当前 Preset 没有兼容能力时，说明缺失能力和可行的手工步骤，不另起运行时。`,\n  \"story-long-scan\": `# story-long-scan — DSH 原生长篇扫榜\n\n基于可核验样本识别长篇网文趋势，不运行打包脚本、不提取登录凭据，也不绕过验证码、\n访问控制或站点限制。\n\n1. 沿用作者已给的条件；缺的一次问齐并给选项：平台（起点/番茄/晋江/七猫/刺猬猫/\n   多个平台对比）、频道（只有番茄、七猫分男频/女频/都看）、看新书里在冒头的还是成熟\n   大盘、有没有关注的题材方向（没有就做全榜概览）。\n2. 数据来源依次为：用户提供的数据或链接、当前 DSH Preset 可见的网页工具、\n   references/genre-trends.md 中的历史趋势。无法获取实时数据时必须明确标为历史假设。\n3. 每个样本记录来源 URL、采集日期、榜单口径、有效条目数、缺失字段和异常项；\n   不把搜索摘要、推断或过期缓存写成页面事实。\n4. 按题材分布、新题材信号、经典题材变化、篇幅与更新、书名模式、开头卖点和\n   差异化元素分析。题材热度按热度中位从高到低排，与全平台比较用白话（如「比全平台\n   四分之三的书都热」）；头部老书只代表存量读者；没有可比的上期样本时趋势写「未比较」。需要决策门禁时使用 references/topic-decision.md。\n5. 输出市场概况、题材热度、证据与可信度、风险、三项可执行方向和下次复扫时间。\n6. 报告写给作者：讲市场结论和能写的方向；脚本名、命令和采集状态码不进报告。\n   某个榜没采到，就用一句话说明「XX 榜这次没拿到（原因），结论不含它」。\n7. 每次扫榜新建 扫榜/{YYYYMMDD}/（同日再扫加 -2），样本记录存在这里；报告同时按\n   references/topic-decision.md 的模板写进该目录的 选题决策.md（带「扫榜日期」），\n   作为「扫榜结论」一节，作者要选题时再写「推荐选题」一节。story-long-write 开书时\n   从这份文件接上，所以结论要落盘，不只留在对话里。「推荐选题」每个选题按模板列\n   1-2 本建议拆的对标书（优先新书榜、书库新书中字数不多的同方向书，头部老书只作\n   参照），并告诉作者可用 story-long-analyze 拆它们来验证「能爆的原因」。\n\n当前 Preset 没有网页能力且用户也未提供样本时，使用内置参考完成方法论分析，\n并列出仍需核验的榜单；不要启动 CDP、独立浏览器或并行运行时。`,\n  \"story-short-scan\": `# story-short-scan — DSH 原生短篇扫榜\n\n基于可核验样本识别短篇市场的情绪、题材与传播信号，不运行打包脚本、不读取 Cookie\n或 token，也不绕过验证码、登录或访问控制。\n\n1. 沿用作者已给的平台或方向，缺项一次问齐：想看哪个平台、男频还是女频、哪类短篇；\n   知乎盐言、番茄和七猫短篇请作者发榜单截图、文字或链接；手里有编辑的征稿要求也一起\n   发来。征稿要求原文存进本次扫榜目录的 征稿要求.md，题材、字数、截止日期当硬条件。\n2. 数据来源依次为：用户提供的数据或链接、当前 DSH Preset 可见的网页工具、\n   references/real-market-data.md 中的历史资料。无法联网时必须把结论标为候选假设。\n3. 记录来源 URL、采集日期、榜单口径、有效样本数、缺失字段和异常项。\n4. 分析情绪类型（意难平/反转震撼/爽感释放/治愈温暖/细思极恐/共鸣感动）、题材热点、\n   篇幅、开头、结尾、标题、人设与传播触发点；给每个趋势标注证据强度、饱和风险和有效期。\n   点众、黑岩是在架书目而非热度榜：只有它们的数据时写「在架数量」，不说哪篇火。\n   只有一期样本时不写「变化」。\n5. 输出市场概况（扫榜时间、核心发现和可信度：样本多少篇、来自哪几个榜，并建议\n   哪天前后再扫一次）、情绪热度、题材热点、关键数据、风口预警、三项可写方向。\n6. 报告写给作者：讲市场结论和能写的方向；脚本名、命令和 SKIP 这类采集状态不进报告。\n   某个平台没采到，就用一句话说明「XX 这次没拿到（原因），结论不含它」。\n7. 每次扫榜新建 扫榜/{YYYYMMDD}/（同日再扫加 -2），样本记录存在这里；报告同时按\n   references/topic-match.md 的模板写进该目录的 短篇扫榜结论.md，作为「扫榜结论」\n   一节，结合项目条件再写「选题匹配」一节，目标平台按 topic-match.md 的平台对照写。\n   作者不答投稿平台、素材和字数时按样本给方向，可行性最高写「中」。\n   story-short-write 从这份文件接上选题。\n   作者自己给榜单时，按 references/manual-rank-input.md 的格式整理。\n\n当前 Preset 没有网页能力且用户也未提供样本时，只做历史资料分析并列出验证动作；\n不要启动 CDP、独立浏览器或并行运行时。`\n};\n\ninterface ParsedSkill {\n  readonly name: string;\n  readonly description: string;\n  readonly content: string;\n  readonly userInvocable: boolean;\n}\n\nfunction frontmatterValue(frontmatter: string, key: string): string | undefined {\n  const lines = frontmatter.split(/\\r?\\n/u);\n  const index = lines.findIndex((line) => new RegExp(`^${key}:\\\\s*`, \"u\").test(line));\n  if (index < 0) return undefined;\n  const raw = lines[index]?.replace(new RegExp(`^${key}:\\\\s*`, \"u\"), \"\").trim();\n  if (raw === undefined) return undefined;\n  if (raw === \">\" || raw === \"|\" || raw === \">-\" || raw === \"|-\") {\n    const values: string[] = [];\n    for (const line of lines.slice(index + 1)) {\n      if (/^\\S/u.test(line)) break;\n      values.push(line.trim());\n    }\n    return (raw.startsWith(\">\") ? values.join(\" \") : values.join(\"\\n\")).trim();\n  }\n  if (raw.startsWith(\"\\\"\") && raw.endsWith(\"\\\"\")) {\n    try { return JSON.parse(raw) as string; }\n    catch { return raw.slice(1, -1); }\n  }\n  return raw.replace(/^['\"]|['\"]$/gu, \"\");\n}\n\nexport function parseBundledSkill(source: string): ParsedSkill {\n  const match = /^---\\r?\\n([\\s\\S]*?)\\r?\\n---\\r?\\n?/u.exec(source);\n  if (match?.[1] === undefined) throw new Error(\"Bundled skill is missing YAML frontmatter.\");\n  const name = frontmatterValue(match[1], \"name\");\n  const description = frontmatterValue(match[1], \"description\");\n  if (!name || !/^[a-z0-9]+(?:-[a-z0-9]+)*$/u.test(name)) throw new Error(\"Bundled skill has an invalid name.\");\n  if (!description) throw new Error(`Bundled skill \"${name}\" has no description.`);\n  return {\n    name,\n    description,\n    content: source.slice(match[0].length),\n    userInvocable: frontmatterValue(match[1], \"user-invocable\") !== \"false\"\n  };\n}\n\nexport function dshSkillContent(name: string, content: string): string {\n  const override = DSH_SKILL_OVERRIDES[name];\n  const native = DSH_NATIVE_SKILLS[name];\n  return `${DSH_SKILL_BRIDGE}${override === undefined ? \"\" : `\\n<skill-specific-dsh-override>${override}</skill-specific-dsh-override>`}\\n\\n${native ?? content}`;\n}\n\nexport function defaultBundledSkillRoot(): string {\n  const current = dirname(fileURLToPath(import.meta.url));\n  return basename(current) === \"src\"\n    ? resolve(current, \"../../knowledge/oh-story/skills\")\n    : resolve(current, \"oh-story/skills\");\n}\n\nexport function defaultDramaSkillRoot(): string {\n  const current = dirname(fileURLToPath(import.meta.url));\n  return basename(current) === \"src\"\n    ? resolve(current, \"../../knowledge/drama/skills\")\n    : resolve(current, \"drama/skills\");\n}\n\nexport function defaultNovelToGameSkillRoot(): string {\n  const current = dirname(fileURLToPath(import.meta.url));\n  return basename(current) === \"src\"\n    ? resolve(current, \"../../knowledge/novel-to-game/skills\")\n    : resolve(current, \"novel-to-game/skills\");\n}\n\nfunction createBundledSkillProvider(\n  providerName: string,\n  skillRoot: string,\n  content: (name: string, source: string) => string\n): SkillProvider {\n  const root = resolve(skillRoot);\n  return {\n    name: providerName,\n    async list(): Promise<readonly SkillCandidate[]> {\n      const directories = (await readdir(root, { withFileTypes: true }))\n        .filter((entry) => entry.isDirectory())\n        .map((entry) => entry.name)\n        .sort();\n      return Promise.all(directories.map(async (directory): Promise<SkillCandidate> => {\n        const path = join(root, directory, \"SKILL.md\");\n        const parsed = parseBundledSkill(await readFile(path, \"utf8\"));\n        if (parsed.name !== directory) throw new Error(`Bundled skill directory \"${directory}\" does not match name \"${parsed.name}\".`);\n        return {\n          name: parsed.name,\n          description: parsed.description,\n          invocation: { modelInvocable: true, userInvocable: parsed.userInvocable },\n          provider: providerName,\n          source: \"bundled\",\n          resourceBase: { kind: \"directory\", path: join(root, directory) },\n          rank: BUNDLED_SKILL_RANK,\n          locator: pathToFileURL(path),\n          path\n        };\n      }));\n    },\n    async get(candidate): Promise<SkillDefinition | undefined> {\n      if (candidate.provider !== providerName || typeof candidate.path !== \"string\") return undefined;\n      const path = resolve(candidate.path);\n      const relativePath = relative(root, path);\n      if (relativePath === \"\" || relativePath.startsWith(\"..\") || isAbsolute(relativePath)) {\n        throw new Error(\"Bundled skill locator escaped the packaged skill root.\");\n      }\n      const parsed = parseBundledSkill(await readFile(path, \"utf8\"));\n      if (parsed.name !== candidate.name) return undefined;\n      return {\n        name: parsed.name,\n        description: parsed.description,\n        invocation: { modelInvocable: true, userInvocable: parsed.userInvocable },\n        provider: providerName,\n        source: \"bundled\",\n        resourceBase: { kind: \"directory\", path: join(root, parsed.name) },\n        path,\n        content: content(parsed.name, parsed.content)\n      };\n    }\n  };\n}\n\nexport function createOhStorySkillProvider(skillRoot = defaultBundledSkillRoot()): SkillProvider {\n  return createBundledSkillProvider(STORY_PROVIDER_NAME, skillRoot, dshSkillContent);\n}\n\nexport function dshDramaSkillContent(name: string, content: string, skillRoot = defaultDramaSkillRoot()): string {\n  const entry = DSH_DRAMA_OVERRIDES[name];\n  // Resolved per read, not at import: the config path follows the environment\n  // the host actually runs with, and matches what /oh-story/drama-preflight reports.\n  const override = typeof entry === \"function\" ? entry(skillRoot) : entry;\n  return `${DSH_DRAMA_BRIDGE}${override === undefined ? \"\" : `\\n<skill-specific-dsh-override>${override}</skill-specific-dsh-override>`}\\n\\n${content}`;\n}\n\nexport function createDramaSkillProvider(skillRoot = defaultDramaSkillRoot()): SkillProvider {\n  return createBundledSkillProvider(DRAMA_PROVIDER_NAME, skillRoot, (name, content) => dshDramaSkillContent(name, content, skillRoot));\n}\n\nexport function dshNovelToGameSkillContent(_name: string, content: string): string {\n  return `${DSH_GAME_BRIDGE}\\n\\n${content}`;\n}\n\nexport function createNovelToGameSkillProvider(skillRoot = defaultNovelToGameSkillRoot()): SkillProvider {\n  return createBundledSkillProvider(GAME_PROVIDER_NAME, skillRoot, dshNovelToGameSkillContent);\n}\n\nexport function defaultVideoRecapSkillRoot(): string {\n  const current = dirname(fileURLToPath(import.meta.url));\n  return basename(current) === \"src\"\n    ? resolve(current, \"../../knowledge/video-recap/skills\")\n    : resolve(current, \"video-recap/skills\");\n}\n\nexport function dshVideoRecapSkillContent(_name: string, content: string): string {\n  return `${DSH_VIDEO_BRIDGE}\\n\\n${content}`;\n}\n\nexport function createVideoRecapSkillProvider(skillRoot = defaultVideoRecapSkillRoot()): SkillProvider {\n  return createBundledSkillProvider(VIDEO_PROVIDER_NAME, skillRoot, dshVideoRecapSkillContent);\n}\n"
    },
    {
      "path": "packages/dsh-plugin/src/workspace-route.ts",
      "content": "import { createHash } from \"node:crypto\";\nimport { createReadStream } from \"node:fs\";\nimport { readFile as readNodeFile, realpath as nodeRealpath, stat as nodeStat } from \"node:fs/promises\";\nimport type { IncomingMessage, ServerResponse } from \"node:http\";\nimport { extname, isAbsolute, relative, resolve } from \"node:path\";\nimport type { Context } from \"@deepseek-ai/cordis\";\nimport type { Agent } from \"@deepseek-ai/dsh-agent\";\nimport { FsError, type FileSystem, type FsInfo, type FsTarget, type FsVersion } from \"@deepseek-ai/dsh-fs\";\nimport type {} from \"@deepseek-ai/dsh-host-webserver\";\nimport type { SandboxPolicyService } from \"@deepseek-ai/dsh-sandbox-policy\";\nimport { SessionId } from \"@deepseek-ai/dsh-session\";\nimport type {} from \"@deepseek-ai/dsh-typert-registry\";\nimport { type GameVerificationBinding, WorkspaceVerificationTracker } from \"./game-verification.js\";\nimport { dramaAdapterStatuses, ensureDramaAdapterConfig, type DramaAdapterStatus } from \"./drama-adapters.js\";\nimport { commandOutput, DRAMA_PYTHON, hostPython, VIDEO_PYTHON, type PythonProbe } from \"./host-python.js\";\nimport { defaultDramaSkillRoot, defaultNovelToGameSkillRoot } from \"./skill-provider.js\";\nimport { skipVideoDirectory, summarizeVideoProject, VIDEO_DIRECTORY, videoProjectRoot, visibleVideoPath, type VideoProjectSummary } from \"./video-project.js\";\nimport { isTrustedPreviewNavigation, isTrustedWorkspaceRequest } from \"./workspace-request-trust.js\";\n\nconst STORY_DIRECTORIES = [\"正文\", \"大纲\", \"设定\", \"追踪\", \"对标\", \"参考资料\"] as const;\nconst DRAMA_DIRECTORIES = [\"输入\", \"项目开发\", \"设定集\", \"剧集\", \"交付\", \"创作者决策\", \"审查\"] as const;\nconst GAME_DIRECTORY = \"game-adaptations\";\n// Preview studios need only a small manifest-driven subset, so discover them before a very large\n// prose workspace can consume the shared listing budget.\nconst CREATIVE_DIRECTORIES = [VIDEO_DIRECTORY, GAME_DIRECTORY, ...STORY_DIRECTORIES, ...DRAMA_DIRECTORIES] as const;\n// Oh Story short fiction keeps one book as three files at the book root (DSH: the workspace root).\nconst SHORT_STORY_FILES = [\"正文.md\", \"设定.md\", \"小节大纲.md\"] as const;\nconst ROOT_FILES = new Set<string>([\"short-drama.json\", ...SHORT_STORY_FILES]);\nconst EDITABLE_EXTENSIONS = new Set([\".md\", \".txt\", \".json\", \".jsonl\"]);\nconst GAME_EDITABLE_EXTENSIONS = new Set([...EDITABLE_EXTENSIONS, \".html\", \".css\", \".js\", \".mjs\", \".cjs\", \".ts\", \".tsx\", \".jsx\"]);\nconst VIDEO_EDITABLE_EXTENSIONS = new Set([...EDITABLE_EXTENSIONS, \".srt\", \".ass\"]);\nconst MEDIA_TYPES: ReadonlyMap<string, string> = new Map([\n  [\".png\", \"image/png\"], [\".jpg\", \"image/jpeg\"], [\".jpeg\", \"image/jpeg\"], [\".webp\", \"image/webp\"], [\".gif\", \"image/gif\"],\n  [\".mp4\", \"video/mp4\"], [\".webm\", \"video/webm\"], [\".mov\", \"video/quicktime\"], [\".mkv\", \"video/x-matroska\"],\n  [\".mp3\", \"audio/mpeg\"], [\".wav\", \"audio/wav\"], [\".m4a\", \"audio/mp4\"], [\".aac\", \"audio/aac\"], [\".flac\", \"audio/flac\"]\n]);\nconst MEDIA_MAX_BYTES = 256 * 1_024 * 1_024;\nconst FILE_LIMIT = 1_000;\nconst PREVIEW_FILE_LIMIT = 32 * 1024 * 1024;\nconst BUNDLED_GAME_EXAMPLE = \"jin-ping-mei\";\nconst workspaceVerificationTracker = new WorkspaceVerificationTracker();\nlet videoPreflightCache: { readonly expires: number; readonly value: VideoPreflightSummary } | undefined;\nlet dramaPreflightCache: { readonly expires: number; readonly value: DramaPreflightSummary } | undefined;\n\ninterface WorkspaceRouteOptions {\n  readonly maxBytes: number;\n  readonly trustedHosts?: readonly string[];\n}\n\n/** Host-process capability probe. The Agent's execution world may differ; `video-recap --doctor` is authoritative there. */\ninterface VideoPreflightSummary {\n  readonly python: PythonProbe;\n  readonly ffmpeg: { readonly ok: boolean; readonly subtitles: boolean };\n  readonly ffprobe: { readonly ok: boolean };\n  readonly credentials: { readonly mimo: boolean; readonly fish: boolean; readonly indexTts: boolean; readonly ttsProvider: string };\n}\n\ninterface WorkspaceFile {\n  readonly path: string;\n  readonly bytes: number;\n  readonly version: string;\n  readonly kind: \"text\" | \"media\";\n  readonly mimeType?: string | undefined;\n}\n\ninterface GameVerificationSummary {\n  readonly status: \"NOT_RUN\" | \"FAIL\" | \"PASS\";\n  readonly checks: Readonly<Record<string, \"NOT_RUN\" | \"FAIL\" | \"PASS\">>;\n  readonly runId?: string | undefined;\n  readonly limitations: readonly { readonly scope: string; readonly reason: string }[];\n  readonly binding: GameVerificationBinding;\n  readonly verifiedPreviewVersion?: string | undefined;\n}\n\ninterface GameProjectSummary {\n  readonly id: string;\n  readonly root: string;\n  readonly title: string;\n  readonly source: \"workspace\" | \"example\";\n  readonly previewReady: boolean;\n  readonly previewUrl?: string | undefined;\n  readonly previewVersion: string;\n  readonly verification: GameVerificationSummary;\n}\n\ninterface WorkspaceRealm {\n  readonly agent: Agent;\n  readonly fs: FileSystem;\n  readonly sandboxPolicy: SandboxPolicyService;\n  readonly cwd: string;\n  readonly root: FsTarget;\n}\n\ninterface ReadFileResult {\n  readonly content: string;\n  readonly bytes: number;\n  readonly version: FsVersion;\n}\n\nclass WorkspaceHttpError extends Error {\n  constructor(readonly status: number, message: string) { super(message); }\n}\n\nfunction configured(...names: readonly string[]): boolean {\n  return names.some((name) => (process.env[name] ?? \"\") !== \"\");\n}\n\n/**\n * Host-process view of short-drama production: which bundled media adapters\n * have their environment set, and where the adapter config the Agent passes to\n * `production_tool.py run` lives. Values never leave the process.\n */\ninterface DramaPreflightSummary {\n  readonly python: PythonProbe;\n  readonly adapterConfig: { readonly path: string; readonly generated: boolean; readonly ok: boolean };\n  readonly adapters: readonly DramaAdapterStatus[];\n}\n\nlet dramaPreflightInFlight: Promise<DramaPreflightSummary> | undefined;\n\nasync function dramaPreflight(): Promise<DramaPreflightSummary> {\n  if (dramaPreflightCache !== undefined && dramaPreflightCache.expires > Date.now()) return dramaPreflightCache.value;\n  // One probe per cache miss: concurrent requests share the write instead of\n  // racing it, and the write itself is atomic (temp file + rename).\n  dramaPreflightInFlight ??= (async () => {\n    try {\n      const python = await hostPython(DRAMA_PYTHON);\n      const adapterConfig = await ensureDramaAdapterConfig(defaultDramaSkillRoot(), { python: python.command });\n      const value = { python: python.probe, adapterConfig, adapters: dramaAdapterStatuses() };\n      dramaPreflightCache = { expires: Date.now() + 30_000, value };\n      return value;\n    } finally { dramaPreflightInFlight = undefined; }\n  })();\n  return dramaPreflightInFlight;\n}\n\nasync function videoPreflight(): Promise<VideoPreflightSummary> {\n  if (videoPreflightCache !== undefined && videoPreflightCache.expires > Date.now()) return videoPreflightCache.value;\n  const python = (await hostPython(VIDEO_PYTHON)).probe;\n  const [ffmpegOutput, ffmpegFilters, ffprobeOutput] = await Promise.all([\n    commandOutput(\"ffmpeg\", [\"-version\"]),\n    commandOutput(\"ffmpeg\", [\"-hide_banner\", \"-filters\"]),\n    commandOutput(\"ffprobe\", [\"-version\"])\n  ]);\n  const value = {\n    python,\n    ffmpeg: { ok: ffmpegOutput !== undefined, subtitles: /\\bsubtitles\\b/u.test(ffmpegFilters ?? \"\") },\n    ffprobe: { ok: ffprobeOutput !== undefined },\n    credentials: {\n      // Upstream falls back to the shared MIMO_API_KEY only when a per-service key is unset.\n      mimo: configured(\"MIMO_API_KEY\", \"MIMO_VIDEO_API_KEY\", \"MIMO_TTS_API_KEY\", \"MIMO_ASR_API_KEY\"),\n      fish: configured(\"FISH_API_KEY\"),\n      // index-tts fails before any request unless both are set (video-voiceover/references/index-tts.md).\n      indexTts: configured(\"INDEX_TTS_ENDPOINT\") && configured(\"INDEX_TTS_VOICE\"),\n      // Upstream accepts auto | mimo-tts | fish-audio | index-tts and defaults to auto (voiceover.py).\n      ttsProvider: (process.env.TTS_PROVIDER ?? \"\").trim().toLowerCase() || \"auto\"\n    }\n  };\n  videoPreflightCache = { expires: Date.now() + 30_000, value };\n  return value;\n}\n\nfunction send(response: ServerResponse, status: number, value: unknown): void {\n  const body = `${JSON.stringify(value)}\\n`;\n  response.writeHead(status, {\n    \"content-type\": \"application/json; charset=utf-8\",\n    \"content-length\": Buffer.byteLength(body),\n    \"cache-control\": \"no-store\",\n    \"x-content-type-options\": \"nosniff\"\n  });\n  response.end(body);\n}\n\nexport interface ByteRange { readonly start: number; readonly end: number }\n\n/**\n * RFC 9110 14.2: a Range this server cannot parse or does not support is ignored (`undefined`, full\n * 200 response); only a well-formed but unsatisfiable range earns a 416 (`null`).\n */\nexport function parseByteRange(value: string | undefined, size: number): ByteRange | undefined | null {\n  const match = value === undefined ? null : /^bytes=(\\d*)-(\\d*)$/u.exec(value.trim());\n  if (match === null) return undefined;\n  const left = match[1] ?? \"\";\n  const right = match[2] ?? \"\";\n  if (left === \"\") {\n    const suffix = Number(right);\n    if (right === \"\" || !Number.isSafeInteger(suffix)) return undefined;\n    return suffix === 0 || size <= 0 ? null : { start: Math.max(0, size - suffix), end: size - 1 };\n  }\n  const start = Number(left);\n  const requestedEnd = right === \"\" ? Number.MAX_SAFE_INTEGER : Number(right);\n  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(requestedEnd) || requestedEnd < start) return undefined;\n  return start >= size ? null : { start, end: Math.min(requestedEnd, size - 1) };\n}\n\nfunction mediaHeaders(mimeType: string, size: number, range: ByteRange | undefined): Record<string, string | number> {\n  const start = range?.start ?? 0;\n  const end = range?.end ?? size - 1;\n  return {\n    \"content-type\": mimeType,\n    \"content-length\": Math.max(0, end - start + 1),\n    \"cache-control\": \"private, max-age=60\",\n    \"accept-ranges\": \"bytes\",\n    ...(range === undefined ? {} : { \"content-range\": `bytes ${String(start)}-${String(end)}/${String(size)}` }),\n    \"x-content-type-options\": \"nosniff\"\n  };\n}\n\nfunction sendMediaBytes(request: IncomingMessage, response: ServerResponse, bytes: Uint8Array, mimeType: string): void {\n  const range = parseByteRange(typeof request.headers.range === \"string\" ? request.headers.range : undefined, bytes.byteLength);\n  if (range === null) {\n    response.writeHead(416, { \"content-range\": `bytes */${String(bytes.byteLength)}`, \"cache-control\": \"no-store\" });\n    response.end();\n    return;\n  }\n  const start = range?.start ?? 0;\n  const end = range?.end ?? bytes.byteLength - 1;\n  const body = bytes.subarray(start, end + 1);\n  response.writeHead(range === undefined ? 200 : 206, mediaHeaders(mimeType, bytes.byteLength, range));\n  response.end(request.method === \"HEAD\" ? undefined : Buffer.from(body));\n}\n\n/**\n * Resolve the target to a path this web host may open directly, or `undefined` when it may not.\n * `processPath` is canonical in the backend's execution world, which is not necessarily this\n * process's, so containment is re-checked against the host-visible workspace root: a remote path\n * that happens to exist locally never becomes a stream.\n */\nasync function hostWorkspaceFile(realm: WorkspaceRealm, target: FsTarget, expectedSize: number): Promise<string | undefined> {\n  const [root, path] = await Promise.all([\n    nodeRealpath(realm.fs.processPath(realm.root)),\n    nodeRealpath(realm.fs.processPath(target))\n  ]);\n  const inside = relative(root, path);\n  if (inside === \"\" || inside.startsWith(\"..\") || isAbsolute(inside)) return undefined;\n  const local = await nodeStat(path);\n  return local.isFile() && local.size === expectedSize ? path : undefined;\n}\n\nasync function sendWorkspaceMedia(request: IncomingMessage, response: ServerResponse, realm: WorkspaceRealm, target: FsTarget, info: FsInfo, mimeType: string): Promise<void> {\n  const expectedSize = info.size;\n  if (expectedSize !== undefined) {\n    // A remote filesystem may expose a process path this web host cannot read; fall back to its\n    // bounded binary API for modest files.\n    const processPath = await hostWorkspaceFile(realm, target, expectedSize).catch(() => undefined);\n    if (processPath !== undefined) {\n      const range = parseByteRange(typeof request.headers.range === \"string\" ? request.headers.range : undefined, expectedSize);\n      if (range === null) {\n        response.writeHead(416, { \"content-range\": `bytes */${String(expectedSize)}`, \"cache-control\": \"no-store\" });\n        response.end();\n        return;\n      }\n      response.writeHead(range === undefined ? 200 : 206, mediaHeaders(mimeType, expectedSize, range));\n      if (request.method === \"HEAD\") { response.end(); return; }\n      const stream = createReadStream(processPath, range === undefined ? undefined : { start: range.start, end: range.end });\n      request.once(\"close\", () => { if (!response.writableEnded) stream.destroy(); });\n      stream.on(\"error\", () => { if (!response.headersSent) response.destroy(); else response.end(); });\n      stream.pipe(response);\n      return;\n    }\n    if (expectedSize > MEDIA_MAX_BYTES) throw new WorkspaceHttpError(413, \"远程媒体超过工作台回退预览大小限制。\");\n  }\n  sendMediaBytes(request, response, await realm.fs.readBytes(target, undefined, MEDIA_MAX_BYTES), mimeType);\n}\n\nasync function jsonBody(request: IncomingMessage, maxBytes: number): Promise<Record<string, unknown>> {\n  const chunks: Buffer[] = [];\n  let size = 0;\n  for await (const chunk of request as AsyncIterable<Uint8Array>) {\n    const value = Buffer.from(chunk);\n    size += value.byteLength;\n    if (size > maxBytes) throw new WorkspaceHttpError(413, \"请求内容过大。\");\n    chunks.push(value);\n  }\n  try {\n    const value = JSON.parse(Buffer.concat(chunks).toString(\"utf8\")) as unknown;\n    if (typeof value !== \"object\" || value === null || Array.isArray(value)) throw new Error();\n    return value as Record<string, unknown>;\n  } catch {\n    throw new WorkspaceHttpError(400, \"请求必须是 JSON 对象。\");\n  }\n}\n\nfunction safeRelativePath(path: string): boolean {\n  return path !== \"\"\n    && !path.startsWith(\"/\")\n    && !path.includes(\"\\\\\")\n    && !path.split(\"/\").some((segment) => segment === \"\" || segment === \".\" || segment === \"..\");\n}\n\nfunction editablePath(path: string): boolean {\n  const extensions = path.startsWith(`${GAME_DIRECTORY}/`) ? GAME_EDITABLE_EXTENSIONS\n    : path.startsWith(`${VIDEO_DIRECTORY}/`) ? VIDEO_EDITABLE_EXTENSIONS\n      : EDITABLE_EXTENSIONS;\n  return extensions.has(extname(path).toLocaleLowerCase());\n}\n\nexport function assertCreativePath(path: string, kind: \"text\" | \"media\"): void {\n  if (kind === \"text\" ? !editablePath(path) : !MEDIA_TYPES.has(extname(path).toLocaleLowerCase())) {\n    throw new WorkspaceHttpError(415, kind === \"text\" ? \"工作台不支持编辑该文件类型。\" : \"目标不是受支持的短剧媒体文件。\");\n  }\n  if (!safeRelativePath(path)) {\n    throw new WorkspaceHttpError(403, \"文件路径不在创作工作台中。\");\n  }\n  const root = path.split(\"/\", 1)[0];\n  if (!CREATIVE_DIRECTORIES.some((directory) => directory === root) && !ROOT_FILES.has(path)) {\n    throw new WorkspaceHttpError(403, \"文件路径不在创作工作台中。\");\n  }\n}\n\nexport function mediaMimeTypeForPath(path: string): string | undefined {\n  return MEDIA_TYPES.get(extname(path).toLocaleLowerCase());\n}\n\nasync function workspaceRealmForSession(context: Context, rawId: string): Promise<WorkspaceRealm> {\n  if (rawId === \"\") throw new WorkspaceHttpError(400, \"缺少 DSH sessionId。\");\n  const lookup = context.typert.lookups.get(\"agent\");\n  if (lookup === undefined) throw new WorkspaceHttpError(503, \"DSH Agent lookup 当前不可用。\");\n  let agent: Agent | undefined;\n  try {\n    agent = await lookup.resolve(SessionId(rawId)) as Agent | undefined;\n  } catch {\n    throw new WorkspaceHttpError(404, \"DSH 会话不可用。\");\n  }\n  if (agent === undefined) throw new WorkspaceHttpError(404, \"DSH 会话不可用。\");\n  if (agent.session.header.parentSession !== undefined || agent.session.header.origin === \"subagent\") {\n    throw new WorkspaceHttpError(403, \"子 Agent 会话不开放创作编辑器。\");\n  }\n  const cwd = agent.session.header.cwd;\n  if (cwd === undefined) throw new WorkspaceHttpError(409, \"当前 DSH 会话没有工作目录。\");\n  const fs = agent.ctx.get(\"fs\");\n  const sandboxPolicy = agent.ctx.get(\"sandboxPolicy\");\n  if (fs === undefined || sandboxPolicy === undefined) throw new WorkspaceHttpError(503, \"DSH 文件系统当前不可用。\");\n  return { agent, fs, sandboxPolicy, cwd, root: await fs.resolve(cwd) };\n}\n\nasync function workspaceRealm(context: Context, url: URL): Promise<WorkspaceRealm> {\n  const rawId = url.searchParams.get(\"sessionId\");\n  if (rawId === null) throw new WorkspaceHttpError(400, \"缺少 DSH sessionId。\");\n  return workspaceRealmForSession(context, rawId);\n}\n\nasync function creativeTarget(realm: WorkspaceRealm, path: string, kind: \"text\" | \"media\" = \"text\"): Promise<FsTarget> {\n  assertCreativePath(path, kind);\n  const target = await realm.fs.resolve(path, { cwd: realm.cwd });\n  if (!realm.fs.contains(realm.root, target)) throw new WorkspaceHttpError(403, \"文件路径离开了 DSH 工作目录。\");\n  return target;\n}\n\nfunction requireRegularFile(info: FsInfo | undefined): FsInfo {\n  if (info === undefined) throw new WorkspaceHttpError(404, \"文件不存在。\");\n  if (info.type !== \"file\") throw new WorkspaceHttpError(415, \"目标不是可编辑的普通文件。\");\n  return info;\n}\n\n/** Read bytes and a matching opaque version, retrying if a writer wins the read window. */\nasync function readVersionedFile(fs: FileSystem, target: FsTarget, maxBytes: number): Promise<ReadFileResult> {\n  for (let attempt = 0; attempt < 3; attempt += 1) {\n    const before = requireRegularFile(await fs.stat(target));\n    if (before.size !== undefined && before.size > maxBytes) throw new WorkspaceHttpError(413, \"文件超过工作台大小限制。\");\n    const bytes = await fs.readBytes(target, undefined, maxBytes);\n    const after = requireRegularFile(await fs.stat(target));\n    if (before.version !== after.version) continue;\n    let content: string;\n    try {\n      content = new TextDecoder(\"utf-8\", { fatal: true }).decode(bytes);\n    } catch {\n      throw new WorkspaceHttpError(415, \"文件不是有效的 UTF-8 文本。\");\n    }\n    return { content, bytes: bytes.byteLength, version: after.version };\n  }\n  throw new WorkspaceHttpError(409, \"文件正在被修改，请重试。\");\n}\n\nasync function listFiles(realm: WorkspaceRealm): Promise<WorkspaceFile[]> {\n  const files: WorkspaceFile[] = [];\n  const walk = async (path: string, directory: FsTarget): Promise<void> => {\n    for (const entry of await realm.fs.listDir(directory)) {\n      if (entry.name.startsWith(\".\") || !realm.fs.contains(realm.root, entry.target)) continue;\n      const childPath = `${path}/${entry.name}`;\n      if (entry.type === \"directory\") {\n        if (!skipVideoDirectory(childPath)) await walk(childPath, entry.target);\n      }\n      else if (entry.type === \"file\" && (editablePath(childPath) || MEDIA_TYPES.has(extname(entry.name).toLocaleLowerCase()))) {\n        const info = entry.version === undefined || entry.size === undefined ? await realm.fs.stat(entry.target) : undefined;\n        const version = entry.version ?? info?.version;\n        const mimeType = MEDIA_TYPES.get(extname(entry.name).toLocaleLowerCase());\n        if (version !== undefined && (!childPath.startsWith(`${VIDEO_DIRECTORY}/`) || visibleVideoPath(childPath))) {\n          files.push({ path: childPath, bytes: entry.size ?? info?.size ?? 0, version, kind: mimeType === undefined ? \"text\" : \"media\", mimeType });\n        }\n      }\n      if (files.length >= FILE_LIMIT) return;\n    }\n  };\n  for (const directory of CREATIVE_DIRECTORIES) {\n    const target = await realm.fs.resolve(directory, { cwd: realm.cwd });\n    if (!realm.fs.contains(realm.root, target)) continue;\n    const info = await realm.fs.stat(target);\n    if (info?.type === \"directory\") await walk(directory, target);\n    if (files.length >= FILE_LIMIT) break;\n  }\n  for (const path of ROOT_FILES) {\n    const target = await creativeTarget(realm, path);\n    const info = await realm.fs.stat(target);\n    if (info?.type === \"file\") files.push({ path, bytes: info.size ?? 0, version: info.version, kind: \"text\" });\n  }\n  return files.sort((left, right) => left.path.localeCompare(right.path, \"zh-Hans-CN\"));\n}\n\nasync function metadata(realm: WorkspaceRealm, files: readonly WorkspaceFile[], path: string, maxBytes: number): Promise<{ readonly value: unknown; readonly error?: string }> {\n  if (!files.some((file) => file.path === path)) return { value: null };\n  try {\n    const target = await creativeTarget(realm, path);\n    return { value: JSON.parse((await readVersionedFile(realm.fs, target, maxBytes)).content) as unknown };\n  } catch (error) {\n    return { value: null, error: error instanceof SyntaxError ? `${path} 不是有效的 JSON。` : `${path} 暂时无法读取。` };\n  }\n}\n\nfunction token(value: string): string {\n  return Buffer.from(value, \"utf8\").toString(\"base64url\");\n}\n\nfunction untoken(value: string): string {\n  try { return Buffer.from(value, \"base64url\").toString(\"utf8\"); }\n  catch { throw new WorkspaceHttpError(400, \"游戏预览标识无效。\"); }\n}\n\nexport function gameRoot(path: string): boolean {\n  // Reject only what is actually unsafe; fs.resolve + fs.contains remain the real boundary.\n  // A stricter slug allowlist silently hid legitimate project names (spaces, ·, leading _, NFD).\n  const parts = path.split(\"/\");\n  const name = parts[1];\n  return parts.length === 2 && parts[0] === GAME_DIRECTORY && name !== undefined\n    && name !== \"\" && name !== \".\" && name !== \"..\" && name.length <= 128\n    && !name.startsWith(\".\") && !name.includes(\"\\\\\");\n}\n\nfunction normalizedVerification(\n  value: unknown,\n  binding: GameVerificationBinding,\n  verifiedPreviewVersion?: string\n): GameVerificationSummary {\n  if (typeof value !== \"object\" || value === null || Array.isArray(value)) {\n    return { status: \"NOT_RUN\", checks: {}, limitations: [], binding };\n  }\n  const record = value as Record<string, unknown>;\n  const status = record.status === \"PASS\" || record.status === \"FAIL\" ? record.status : \"NOT_RUN\";\n  const rawChecks = typeof record.checks === \"object\" && record.checks !== null && !Array.isArray(record.checks)\n    ? record.checks as Record<string, unknown>\n    : {};\n  const checks: Record<string, \"NOT_RUN\" | \"FAIL\" | \"PASS\"> = {};\n  for (const name of [\"launch\", \"render\", \"input\", \"coreLoop\", \"outcome\", \"restart\"]) {\n    const check = rawChecks[name];\n    checks[name] = check === \"PASS\" || check === \"FAIL\" ? check : \"NOT_RUN\";\n  }\n  const completeRun = typeof record.completeRun === \"object\" && record.completeRun !== null && !Array.isArray(record.completeRun)\n    ? record.completeRun as Record<string, unknown>\n    : {};\n  const limitations = Array.isArray(record.limitations) ? record.limitations.flatMap((entry) => {\n    if (typeof entry !== \"object\" || entry === null || Array.isArray(entry)) return [];\n    const item = entry as Record<string, unknown>;\n    return typeof item.scope === \"string\" && typeof item.reason === \"string\"\n      ? [{ scope: item.scope, reason: item.reason }]\n      : [];\n  }) : [];\n  return {\n    status,\n    checks,\n    runId: typeof completeRun.id === \"string\" ? completeRun.id : undefined,\n    limitations,\n    binding,\n    verifiedPreviewVersion\n  };\n}\n\nasync function workspaceText(realm: WorkspaceRealm, path: string, maxBytes: number): Promise<string | undefined> {\n  const target = await realm.fs.resolve(path, { cwd: realm.cwd });\n  if (!realm.fs.contains(realm.root, target) || (await realm.fs.stat(target))?.type !== \"file\") return undefined;\n  return (await readVersionedFile(realm.fs, target, maxBytes)).content;\n}\n\nasync function previewDigest(realm: WorkspaceRealm, projectRoot: string): Promise<{ readonly ready: boolean; readonly version: string }> {\n  const appPath = `${projectRoot}/build/app`;\n  const app = await realm.fs.resolve(appPath, { cwd: realm.cwd });\n  if (!realm.fs.contains(realm.root, app) || (await realm.fs.stat(app))?.type !== \"directory\") return { ready: false, version: \"missing\" };\n  const entries: string[] = [];\n  let ready = false;\n  const visit = async (directory: FsTarget, path: string): Promise<void> => {\n    for (const entry of await realm.fs.listDir(directory)) {\n      if (entry.name.startsWith(\".\") || !realm.fs.contains(app, entry.target)) continue;\n      const childPath = path === \"\" ? entry.name : `${path}/${entry.name}`;\n      if (entry.type === \"directory\") await visit(entry.target, childPath);\n      else if (entry.type === \"file\") {\n        const info = entry.version === undefined ? await realm.fs.stat(entry.target) : undefined;\n        const version = entry.version ?? info?.version;\n        if (version !== undefined) entries.push(`${childPath}\\0${version}`);\n        if (childPath === \"index.html\") ready = true;\n      }\n      if (entries.length >= 5_000) return;\n    }\n  };\n  await visit(app, \"\");\n  return { ready, version: createHash(\"sha256\").update(entries.sort().join(\"\\n\")).digest(\"hex\").slice(0, 16) };\n}\n\n/**\n * The game's name from its brief's first heading, e.g. `# PRODUCT_BRIEF — 《雪夜渡》` → `雪夜渡`.\n * The Studio adds its own 书名号 and separators, so neither the file label nor the work's\n * 书名号 belong in the name.\n */\nexport function gameProjectTitle(content: string | undefined, fallback: string): string {\n  const heading = content?.split(/\\r?\\n/u).find((line) => /^#\\s+/u.test(line));\n  const title = heading?.replace(/^#\\s+/u, \"\")\n    .replace(/^(?:PRODUCT[_ ]BRIEF|产品简报)/iu, \"\")\n    .replace(/^[\\s·・:：|—–-]+/u, \"\")\n    .trim()\n    .replace(/^《([^《》]+)》$/u, \"$1\")\n    .trim();\n  return title || fallback;\n}\n\nasync function workspaceGameProjects(\n  realm: WorkspaceRealm,\n  files: readonly WorkspaceFile[],\n  sessionId: string,\n  maxBytes: number\n): Promise<GameProjectSummary[]> {\n  const roots = [...new Set(files.flatMap((file) => {\n    const parts = file.path.split(\"/\");\n    return parts[0] === GAME_DIRECTORY && parts[1] !== undefined ? [`${GAME_DIRECTORY}/${parts[1]}`] : [];\n  }))].filter(gameRoot).sort();\n  return Promise.all(roots.map(async (root) => {\n    const id = root.slice(`${GAME_DIRECTORY}/`.length);\n    const qaPath = `${root}/qa/verification.json`;\n    const qaFile = files.find((file) => file.path === qaPath);\n    // Isolate per-project metadata failures: an unreadable brief, a non-UTF-8 or oversized\n    // verification file, or a build/app subtree removed mid-rebuild must degrade this one card,\n    // never abort the shared workspace listing (which also carries the story and drama trees).\n    const [brief, qa, preview] = await Promise.all([\n      workspaceText(realm, `${root}/PRODUCT_BRIEF.md`, maxBytes).catch(() => undefined),\n      workspaceText(realm, qaPath, maxBytes).catch(() => undefined),\n      previewDigest(realm, root).catch(() => ({ ready: false, version: \"unavailable\" }))\n    ]);\n    let verification: unknown;\n    try { verification = qa === undefined ? undefined : JSON.parse(qa) as unknown; }\n    catch { verification = undefined; }\n    const freshness = workspaceVerificationTracker.observe(`${sessionId}\\0${root}`, qaFile?.version, preview.version);\n    return {\n      id: `workspace:${id}`,\n      root,\n      title: gameProjectTitle(brief, id),\n      source: \"workspace\" as const,\n      previewReady: preview.ready,\n      previewUrl: preview.ready\n        ? `/oh-story/game-preview/workspace/${token(sessionId)}/${token(root)}/index.html`\n        : undefined,\n      previewVersion: preview.version,\n      verification: normalizedVerification(verification, freshness.binding, freshness.verifiedPreviewVersion)\n    };\n  }));\n}\n\nasync function workspaceVideoProjects(realm: WorkspaceRealm, files: readonly WorkspaceFile[], maxBytes: number): Promise<VideoProjectSummary[]> {\n  const roots = [...new Set(files.flatMap((file) => {\n    const root = videoProjectRoot(file.path);\n    return root === undefined ? [] : [root];\n  }))].sort((left, right) => left.localeCompare(right, \"zh-Hans-CN\"));\n  return Promise.all(roots.map(async (root) => {\n    const findPath = (name: string): string | undefined => files.find((file) => file.path.startsWith(`${root}/`) && file.path.split(\"/\").at(-1) === name)?.path;\n    const readJson = async (name: string): Promise<unknown> => {\n      const path = findPath(name);\n      if (path === undefined) return undefined;\n      const content = await workspaceText(realm, path, maxBytes).catch(() => undefined);\n      if (content === undefined) return undefined;\n      try { return JSON.parse(content) as unknown; }\n      catch { return undefined; }\n    };\n    const [project, runManifest, assembly] = await Promise.all([\n      readJson(\"project.json\"),\n      readJson(\"recap_run_manifest.json\"),\n      readJson(\"assembly_manifest.json\")\n    ]);\n    return summarizeVideoProject(root, files, { project, runManifest, assembly });\n  }));\n}\n\nfunction bundledExampleRoot(): string {\n  return resolve(defaultNovelToGameSkillRoot(), `../examples/${BUNDLED_GAME_EXAMPLE}`);\n}\n\nasync function bundledGameExample(): Promise<GameProjectSummary> {\n  const root = bundledExampleRoot();\n  const [example, verification, manifest] = await Promise.all([\n    readNodeFile(resolve(root, \"example.json\"), \"utf8\"),\n    readNodeFile(resolve(root, \"qa/verification.json\"), \"utf8\"),\n    readNodeFile(resolve(defaultNovelToGameSkillRoot(), \"../manifest.json\"), \"utf8\")\n  ]);\n  const exampleJson = JSON.parse(example) as { readonly title?: unknown };\n  const manifestJson = JSON.parse(manifest) as { readonly upstream?: { readonly commit?: unknown } };\n  const previewVersion = typeof manifestJson.upstream?.commit === \"string\" ? manifestJson.upstream.commit.slice(0, 16) : \"bundled\";\n  return {\n    id: `example:${BUNDLED_GAME_EXAMPLE}`,\n    root: `examples/${BUNDLED_GAME_EXAMPLE}`,\n    title: typeof exampleJson.title === \"string\" ? exampleJson.title : \"金瓶梅 · 风月总账\",\n    source: \"example\",\n    previewReady: true,\n    previewUrl: `/oh-story/game-preview/example/${BUNDLED_GAME_EXAMPLE}/index.html`,\n    previewVersion,\n    verification: normalizedVerification(JSON.parse(verification) as unknown, \"PINNED\", previewVersion)\n  };\n}\n\nfunction previewContentType(path: string): string {\n  switch (extname(path).toLocaleLowerCase()) {\n    case \".html\": return \"text/html; charset=utf-8\";\n    case \".css\": return \"text/css; charset=utf-8\";\n    case \".js\":\n    case \".mjs\": return \"text/javascript; charset=utf-8\";\n    case \".json\": return \"application/json; charset=utf-8\";\n    case \".svg\": return \"image/svg+xml\";\n    case \".png\": return \"image/png\";\n    case \".jpg\":\n    case \".jpeg\": return \"image/jpeg\";\n    case \".webp\": return \"image/webp\";\n    case \".gif\": return \"image/gif\";\n    case \".woff\": return \"font/woff\";\n    case \".woff2\": return \"font/woff2\";\n    case \".wasm\": return \"application/wasm\";\n    case \".mp3\": return \"audio/mpeg\";\n    case \".ogg\": return \"audio/ogg\";\n    default: return \"application/octet-stream\";\n  }\n}\n\nfunction previewAssetSources(request: IncomingMessage): string {\n  const authority = request.headers.host;\n  if (authority === undefined) return \"'none'\";\n  const prefix = `${authority}/oh-story/game-preview/`;\n  return `http://${prefix} https://${prefix}`;\n}\n\n/**\n * Emitted for EVERY preview response, not just HTML. previewContentType serves .svg as\n * image/svg+xml — an active document type — so a game that self-navigates its frame to a scripted\n * SVG would otherwise land in a document with no policy at all, while the iframe sandbox flags\n * (which do persist across that navigation) still grant it script execution. The `sandbox`\n * directive makes each response self-confining regardless of the iframe attribute.\n */\nexport function previewContentSecurityPolicy(assets: string): string {\n  return [\n    \"sandbox allow-scripts allow-forms allow-modals allow-downloads allow-same-origin\",\n    \"default-src 'none'\",\n    `script-src 'unsafe-inline' 'wasm-unsafe-eval' blob: ${assets}`,\n    `style-src 'unsafe-inline' ${assets}`,\n    `img-src data: blob: ${assets}`,\n    `media-src data: blob: ${assets}`,\n    `font-src data: ${assets}`,\n    `connect-src ${assets}`,\n    `worker-src blob: ${assets}`,\n    `manifest-src ${assets}`,\n    \"object-src 'none'\",\n    \"base-uri 'none'\",\n    \"form-action 'none'\",\n    \"frame-ancestors 'self' http://127.0.0.1:* http://localhost:*\"\n  ].join(\"; \");\n}\n\nfunction sendPreview(request: IncomingMessage, response: ServerResponse, path: string, bytes: Uint8Array): void {\n  const assets = previewAssetSources(request);\n  response.writeHead(200, {\n    \"content-type\": previewContentType(path),\n    \"content-length\": bytes.byteLength,\n    \"cache-control\": \"no-store\",\n    \"x-content-type-options\": \"nosniff\",\n    \"cross-origin-resource-policy\": \"cross-origin\",\n    \"access-control-allow-origin\": \"*\",\n    \"content-security-policy\": previewContentSecurityPolicy(assets),\n  });\n  response.end(bytes);\n}\n\nasync function previewBytes(context: Context, pathname: string): Promise<{ readonly path: string; readonly bytes: Uint8Array }> {\n  let segments: string[];\n  try {\n    segments = pathname.split(\"/\").slice(3).map((segment) => decodeURIComponent(segment));\n  } catch {\n    throw new WorkspaceHttpError(400, \"游戏预览地址无效。\");\n  }\n  const kind = segments.shift();\n  if (kind === \"example\") {\n    const id = segments.shift();\n    const path = segments.join(\"/\") || \"index.html\";\n    if (id !== BUNDLED_GAME_EXAMPLE || !safeRelativePath(path)) throw new WorkspaceHttpError(404, \"游戏示例不存在。\");\n    const appRoot = resolve(bundledExampleRoot(), \"build/app\");\n    const target = resolve(appRoot, path);\n    const escaped = relative(appRoot, target);\n    if (escaped.startsWith(\"..\") || isAbsolute(escaped)) throw new WorkspaceHttpError(403, \"预览资源离开了游戏目录。\");\n    const info = await nodeStat(target).catch(() => undefined);\n    if (!info?.isFile()) throw new WorkspaceHttpError(404, \"预览资源不存在。\");\n    if (info.size > PREVIEW_FILE_LIMIT) throw new WorkspaceHttpError(413, \"预览资源过大。\");\n    return { path, bytes: await readNodeFile(target) };\n  }\n  if (kind === \"workspace\") {\n    const session = segments.shift();\n    const project = segments.shift();\n    const path = segments.join(\"/\") || \"index.html\";\n    if (session === undefined || project === undefined || !safeRelativePath(path)) throw new WorkspaceHttpError(400, \"游戏预览地址无效。\");\n    const realm = await workspaceRealmForSession(context, untoken(session));\n    const root = untoken(project);\n    if (!gameRoot(root)) throw new WorkspaceHttpError(403, \"游戏项目路径无效。\");\n    const appRoot = await realm.fs.resolve(`${root}/build/app`, { cwd: realm.cwd });\n    const target = await realm.fs.resolve(`${root}/build/app/${path}`, { cwd: realm.cwd });\n    if (!realm.fs.contains(realm.root, appRoot) || !realm.fs.contains(appRoot, target)) {\n      throw new WorkspaceHttpError(403, \"预览资源离开了游戏目录。\");\n    }\n    const info = requireRegularFile(await realm.fs.stat(target));\n    if (info.size !== undefined && info.size > PREVIEW_FILE_LIMIT) throw new WorkspaceHttpError(413, \"预览资源过大。\");\n    return { path, bytes: await realm.fs.readBytes(target, undefined, PREVIEW_FILE_LIMIT) };\n  }\n  throw new WorkspaceHttpError(404, \"游戏预览不存在。\");\n}\n\nfunction mapFsError(error: unknown): WorkspaceHttpError | undefined {\n  if (!(error instanceof FsError)) return undefined;\n  switch (error.code) {\n    case \"FS_NOT_FOUND\": return new WorkspaceHttpError(404, \"文件不存在。\");\n    case \"FS_TOO_LARGE\": return new WorkspaceHttpError(413, \"文件超过工作台大小限制。\");\n    case \"FS_NOT_TEXT\":\n    case \"FS_NOT_REGULAR_FILE\": return new WorkspaceHttpError(415, \"目标不是可编辑的文本文件。\");\n    case \"FS_PERMISSION_DENIED\":\n    case \"FS_SANDBOX_DENIED\": return new WorkspaceHttpError(403, \"当前 DSH 权限不允许修改该文件。\");\n    case \"FS_STALE_VERSION\":\n    case \"FS_NOT_OBSERVED\": return new WorkspaceHttpError(412, \"文件已在磁盘上更新。请处理冲突后再保存。\");\n    case \"FS_ABORTED\": return new WorkspaceHttpError(409, \"文件操作已取消。\");\n    default: return new WorkspaceHttpError(500, \"DSH 文件系统操作失败。\");\n  }\n}\n\nasync function handle(context: Context, request: IncomingMessage, response: ServerResponse, options: WorkspaceRouteOptions): Promise<void> {\n  try {\n    const url = new URL(request.url ?? \"/\", \"http://127.0.0.1\");\n    const gamePreview = url.pathname.startsWith(\"/oh-story/game-preview/\");\n    const trusted = gamePreview\n      ? isTrustedPreviewNavigation(request, options.trustedHosts ?? [])\n      : isTrustedWorkspaceRequest(request, options.trustedHosts ?? []);\n    if (!trusted) throw new WorkspaceHttpError(403, \"请求来源不受信任。\");\n    if (gamePreview && request.method === \"GET\") {\n      const preview = await previewBytes(context, url.pathname);\n      sendPreview(request, response, preview.path, preview.bytes);\n      return;\n    }\n    if (url.pathname === \"/oh-story/workspace\" && request.method === \"GET\") {\n      const realm = await workspaceRealm(context, url);\n      const files = await listFiles(realm);\n      const tracking = await metadata(realm, files, \"追踪/_tracking-state.json\", options.maxBytes);\n      const shortDrama = await metadata(realm, files, \"short-drama.json\", options.maxBytes);\n      const metadataErrors = [tracking.error, shortDrama.error].filter((value): value is string => value !== undefined);\n      const sessionId = url.searchParams.get(\"sessionId\");\n      if (sessionId === null) throw new WorkspaceHttpError(400, \"缺少 DSH sessionId。\");\n      const games = [\n        ...await workspaceGameProjects(realm, files, sessionId, options.maxBytes),\n        await bundledGameExample()\n      ];\n      const videos = await workspaceVideoProjects(realm, files, options.maxBytes);\n      send(response, 200, { cwd: realm.cwd, files, games, videos, tracking: tracking.value, shortDrama: shortDrama.value, metadataErrors, mode: \"dsh-session\" });\n      return;\n    }\n    if (url.pathname === \"/oh-story/video-preflight\" && request.method === \"GET\") {\n      send(response, 200, await videoPreflight());\n      return;\n    }\n    if (url.pathname === \"/oh-story/drama-preflight\" && request.method === \"GET\") {\n      send(response, 200, await dramaPreflight());\n      return;\n    }\n    if (url.pathname === \"/oh-story/file\" && request.method === \"GET\") {\n      const realm = await workspaceRealm(context, url);\n      const path = url.searchParams.get(\"path\");\n      if (path === null) throw new WorkspaceHttpError(400, \"缺少文件路径。\");\n      const file = await readVersionedFile(realm.fs, await creativeTarget(realm, path), options.maxBytes);\n      send(response, 200, { path, ...file });\n      return;\n    }\n    if (url.pathname === \"/oh-story/media\" && (request.method === \"GET\" || request.method === \"HEAD\")) {\n      const realm = await workspaceRealm(context, url);\n      const path = url.searchParams.get(\"path\");\n      if (path === null) throw new WorkspaceHttpError(400, \"缺少媒体文件路径。\");\n      const mimeType = mediaMimeTypeForPath(path);\n      if (mimeType === undefined) throw new WorkspaceHttpError(415, \"目标不是受支持的短剧媒体文件。\");\n      const target = await creativeTarget(realm, path, \"media\");\n      const info = requireRegularFile(await realm.fs.stat(target));\n      await sendWorkspaceMedia(request, response, realm, target, info, mimeType);\n      return;\n    }\n    if (url.pathname === \"/oh-story/file\" && request.method === \"PUT\") {\n      const realm = await workspaceRealm(context, url);\n      const path = url.searchParams.get(\"path\");\n      if (path === null) throw new WorkspaceHttpError(400, \"缺少文件路径。\");\n      const input = await jsonBody(request, options.maxBytes * 6 + 1_024);\n      if (typeof input.content !== \"string\") throw new WorkspaceHttpError(400, \"content 必须是字符串。\");\n      if (typeof input.baseVersion !== \"string\" || input.baseVersion === \"\") throw new WorkspaceHttpError(400, \"baseVersion 必须是有效版本。\");\n      if (Buffer.byteLength(input.content) > options.maxBytes) throw new WorkspaceHttpError(413, \"文件超过工作台大小限制。\");\n      const outcome = await realm.fs.writeText(\n        await creativeTarget(realm, path),\n        input.content,\n        { kind: \"replaceIfVersion\", version: input.baseVersion as FsVersion },\n        undefined,\n        realm.sandboxPolicy.resolve({ session: realm.agent.session })\n      );\n      send(response, 200, { path, content: outcome.after, bytes: Buffer.byteLength(outcome.after), version: outcome.version });\n      return;\n    }\n    send(response, 404, { error: \"Oh Story route not found.\" });\n  } catch (error) {\n    const mapped = error instanceof WorkspaceHttpError ? error : mapFsError(error);\n    if (mapped === undefined) context.logger(\"oh-story\").error(\"workspace route failed\", error);\n    send(response, mapped?.status ?? 500, { error: mapped?.message ?? \"Oh Story workspace operation failed.\" });\n  }\n}\n\n/** Mount the narrow editor API on DSH's official web-server extension seam. */\nexport function registerWorkspaceRoute(context: Context, options: WorkspaceRouteOptions): void {\n  context.effect(() => context.webServer.register({\n    kind: \"prefix\",\n    path: \"/oh-story\",\n    handler: (request, response) => handle(context, request, response, options)\n  }), \"oh-story: DSH-session workspace API\");\n}\n"
