le=\"tabpanel\" aria-labelledby={`${compactTabsId}-studio-tab`}><div className=\"oh-game-design-empty\">{error ?? \"正在连接游戏工作台…\"}</div></main>}\n    {workspace !== undefined && gameStudioMounted && <GameStudio\n          sessionId={sessionId}\n          workspace={workspace}\n          building={gameBuilding}\n          selected={selected}\n          gameTab={gameTab}\n          gameProjectId={gameProjectId}\n          hidden={workbench !== \"game\"}\n          onGameTab={setGameTab}\n          onGameProject={setGameProjectId}\n          workbenches={WORKBENCH_MODES}\n          paneId={compactStudioId}\n          labelledBy={`${compactTabsId}-studio-tab`}\n          onWorkbench={selectWorkbench}\n          onCollapse={() => { applyWorkbenchPreference(\"closed\"); }}\n          onSelect={revealPath}\n        />}\n    {workbench === \"video\" && workspace === undefined && <main id={compactVideoStudioId} className=\"oh-video-studio\" role=\"tabpanel\" aria-labelledby={`${compactTabsId}-studio-tab`}><div className=\"oh-video-preview-empty\">{error ?? \"正在连接视频工作台…\"}</div></main>}\n    {workspace !== undefined && videoStudioMounted && <VideoStudio\n          sessionId={sessionId}\n          projects={workspace.videos}\n          running={videoBuilding}\n          projectId={videoProjectId}\n          tab={videoTab}\n          hidden={workbench !== \"video\"}\n          workbenches={WORKBENCH_MODES}\n          paneId={compactVideoStudioId}\n          labelledBy={`${compactTabsId}-studio-tab`}\n          onProject={setVideoProjectId}\n          onTab={setVideoTab}\n          onWorkbench={selectWorkbench}\n          onCollapse={() => { applyWorkbenchPreference(\"closed\"); }}\n        />}\n    {workbench !== \"game\" && workbench !== \"video\" && <>\n    <aside className=\"oh-story-tree\">\n      <div className=\"oh-story-brand\">\n        <span className=\"oh-story-brand-cluster\"><strong>✦ <span>Oh Story</span></strong>{workspaceKind !== undefined && <span className=\"oh-story-kind\">{workspaceKind === \"story\" ? \"小说\" : \"短剧\"}</span>}</span>\n        <span className=\"oh-story-brand-actions\">\n          <button type=\"button\" onClick={reload} title=\"刷新\" aria-label=\"刷新项目文件\">↻</button>\n          <button type=\"button\" onClick={() => { applyWorkbenchPreference(\"closed\"); }} title=\"收起创作工作台\" aria-label=\"收起创作工作台\">×</button>\n        </span>\n      </div>\n      {workspace !== undefined && <div className=\"oh-story-mode-tabs\" role=\"tablist\" aria-label=\"创作工作台\">\n        {WORKBENCH_MODES.map((mode) => <button\n          type=\"button\"\n          role=\"tab\"\n          key={mode}\n          tabIndex={workbench === mode ? 0 : -1}\n          aria-selected={workbench === mode}\n          onKeyDown={(event) => { handleTabKey(event, WORKBENCH_MODES, workbench, selectWorkbench); }}\n          onClick={() => { selectWorkbench(mode); }}\n        >{workbenchLabel(mode)}</button>)}\n      </div>}\n      {error !== undefined && <div className=\"oh-story-error\">{error}</div>}\n      {workspace?.metadataErrors.map((message) => <div className=\"oh-story-warning\" key={message}>{message}</div>)}\n      <nav ref={navRef} aria-label={workbench === \"story\" ? \"小说项目文件\" : \"短剧项目文件\"}>\n        {groups.map(([directory, files]) => {\n          const groupOpen = selectedGroup === directory || expanded[directory] === true;\n          return <details className=\"oh-story-file-group\" key={directory} open={groupOpen} onToggle={(event) => { toggleGroup(directory, event.currentTarget.open); }}>\n            <summary>{directory}<span>{files.length}</span></summary>\n            <FileTreeNodes\n              nodes={buildFileTree(files, directory)}\n              depth={1}\n              expanded={expanded}\n              selected={selected}\n              activityPath={activityPath}\n              onToggle={toggleGroup}\n              onSelect={revealPath}\n            />\n          </details>;\n        })}\n      </nav>\n    </aside>\n    <main className=\"oh-story-editor\">\n      <header>\n        <span className=\"oh-story-editor-path\" title={selected}><span>{selectedLabel}</span><strong>{selectedBasename}</strong></span>\n        <div className=\"oh-story-editor-actions\">\n          {(previewable || productionAvailable) && !selectedMedia && <div className=\"oh-story-editor-tabs\" role=\"tablist\" aria-label={productionAvailable ? \"短剧文档查看方式\" : markdown ? \"Markdown 查看方式\" : \"JSONL 查看方式\"}>\n            {editorModes.map((mode) => <button\n              type=\"button\"\n              role=\"tab\"\n              key={mode}\n              tabIndex={editorMode === mode ? 0 : -1}\n              aria-selected={editorMode === mode}\n              onKeyDown={(event) => { handleTabKey(event, editorModes, editorMode, selectEditorMode); }}\n              onClick={() => { selectEditorMode(mode); }}\n            >{mode === \"preview\" ? \"预览\" : mode === \"source\" ? \"源码\" : \"生产\"}</button>)}\n          </div>}\n          {(dirty || saving) && selected !== undefined && <button className=\"oh-story-save\" type=\"button\" disabled={saving || buffer?.missing === true} onClick={() => { void savePath(selected); }}>\n            {saving ? \"保存中…\" : \"保存\"}\n          </button>}\n        </div>\n      </header>\n      {activity !== undefined && activityPath !== undefined && activityPath === selected && <div className=\"oh-story-stream\" data-stage={activity.stage} role=\"status\" aria-live=\"polite\">● {activity.stage === \"running\" ? \"Agent 正在应用修改\" : \"Agent 正在生成文件内容\"}</div>}\n      {conflict !== undefined && <div className=\"oh-story-conflict\" role=\"alert\">\n        <span>{conflict.message}</span>\n        {conflict.theirs !== undefined && conflict.theirsVersion !== undefined && selected !== undefined && <div>\n          <button type=\"button\" onClick={() => { resolveConflict(false); }}>载入磁盘版本</button>\n          <button type=\"button\" onClick={() => { resolveConflict(true); }}>保留本地草稿</button>\n        </div>}\n      </div>}\n      {fileError !== undefined && <div className=\"oh-story-error\">{fileError}</div>}\n      {selected === undefined\n        ? <div className=\"oh-story-empty\">{workbench === \"story\"\n            ? <>当前 workspace 还没有小说文件。可在右侧 Chat 中运行 <code>/story-setup</code>。</>\n            : <>当前 workspace 还没有短剧项目。可在右侧 Chat 中运行 <code>/short-drama</code>。</>}</div>\n        : selectedMedia && selectedFile !== undefined\n          ? <div className=\"oh-story-media-document\">{selectedFile.mimeType?.startsWith(\"image/\") === true\n              ? <img src={endpoint(\"media\", sessionId, selectedFile.path)} alt={selectedFile.path} />\n              : selectedFile.mimeType?.startsWith(\"audio/\") === true\n                ? <audio src={endpoint(\"media\", sessionId, selectedFile.path)} controls />\n                : <video src={endpoint(\"media\", sessionId, selectedFile.path)} controls preload=\"metadata\" />}</div>\n        : buffer === undefined\n          ? <div className=\"oh-story-empty\">正在加载 {selected}…</div>\n        : buffer.missing === true\n          ? <div className=\"oh-story-empty\">文件已从 workspace 移除，本地草稿仍保留。请先复制需要的内容，再放弃草稿。<button type=\"button\" onClick={() => {\n            setBuffers((current) => {\n              const next = { ...current };\n              delete next[selected];\n              return next;\n            });\n            setSelected(workspace === undefined ? undefined : preferredWorkbenchFile(workspace.files, workbench));\n          }}>放弃本地草稿</button></div>\n        : editorMode === \"production\" && productionAvailable && episodeProduction !== undefined\n          ? <DramaProductionView\n              sessionId={sessionId}\n              production={episodeProduction}\n              sessionRunning={sessionRunning}\n              queue={productionQueue}\n              section={productionSection}\n              selectedId={productionSelectedId}\n              jobs={productionJobs}\n              versions={productionVersions}\n              libraryVersions={productionLibrary}\n              selections={productionSelections}\n              manualReferences={productionReferences}\n              sequence={productionSequence}\n              canvas={productionCanvas}\n              viewport={productionViewport}\n              onSectionChange={setProductionSection}\n              onSelect={setProductionSelectedId}\n              onNavigate={navigateProductionTarget}\n              onJobsChange={setProductionJobs}\n              onSelectionsChange={setProductionSelections}\n              onManualReferencesChange={setProductionReferences}\n              onOpenMedia={(path) => { revealPath(path); }}\n              onSequenceChange={setProductionSequence}\n              onCanvasChange={setProductionCanvas}\n              onViewportChange={setProductionViewport}\n              onDispatchPrompt={sendProductionPrompt}\n              onCancelTurn={cancelProduction}\n              onRemoveQueued={removeQueuedProduction}\n              onRefresh={reload}\n            />\n        : previewable && editorMode === \"preview\"\n          ? markdown\n            ? <MarkdownPreview content={buffer.content} label={selected} />\n            : <JsonlPreview content={buffer.content} label={selected} />\n          : <textarea\n            ref={textareaRef}\n            value={buffer.content}\n            data-format={structured ? \"structured\" : \"prose\"}\n            onBlur={rememberEditorPosition}\n            onScroll={rememberEditorPosition}\n            onSelect={rememberEditorPosition}\n            onChange={(event) => {\n              const content = event.target.value;\n              setBuffers((current) => ({\n                ...current,\n                [selected]: {\n                  content,\n                  saved: current[selected]?.saved ?? \"\",\n                  source: \"human\",\n                  version: current[selected]?.version ?? \"\",\n                  conflict: current[selected]?.conflict,\n                  saving: current[selected]?.saving\n                }\n              }));\n            }}\n            spellCheck={!structured}\n            aria-label={selected}\n          />}\n    </main>\n    </>}\n  </div>;\n}\n\ninterface ProductionConversationFace {\n  readonly sendProductionPrompt: (prompt: string) => Promise<void>;\n  readonly cancelProduction: () => Promise<void>;\n  readonly removeQueuedProduction: (itemId: string) => Promise<void>;\n}\n\ntype WorkbenchSlotProps = PropsRuntime<\"oh-story.workspace\"> & PropsStore<ReturnType<typeof createWorkbenchStore>> & ProductionConversationFace;\n\n/**\n * DSH 0.1.7's SessionProvider stopped keying its subtree by Session, so switching Sessions\n * would carry one Session's selection, drafts and dedup guards into the next. Keep the\n * one-mount-per-Session contract the workbench was written against.\n */\nfunction CreativeSplitBridge(props: WorkbenchSlotProps) {\n  return <SessionWorkbenchMemory key={props.sessionId} {...props} />;\n}\n\n/** Restore this Session's workbench memory into a fresh Store before anything reads it. */\nfunction SessionWorkbenchMemory(props: WorkbenchSlotProps) {\n  const { sessionId, useStore, actions } = props;\n  const hydrated = useStore((state) => state.hydrated);\n  // Nothing renders from a fresh instance: its initial state would be mirrored over the saved\n  // copy, and the workbench's own effects would act on an empty selection.\n  useLayoutEffect(() => {\n    if (!hydrated) actions.restore(workbenchMemoryBySession.get(sessionId));\n  }, [actions, hydrated, sessionId]);\n  return hydrated ? <>\n    <WorkbenchMemoryMirror sessionId={sessionId} useStore={useStore} />\n    <SessionWorkbenchBridge {...props} />\n  </> : null;\n}\n\n/** Keeps the page-lifetime copy current without re-rendering the workbench on every edit. */\nfunction WorkbenchMemoryMirror({ sessionId, useStore }: Pick<WorkbenchSlotProps, \"sessionId\" | \"useStore\">) {\n  const memory = useStore((state) => state);\n  useEffect(() => {\n    workbenchMemoryBySession.set(sessionId, memory);\n  }, [memory, sessionId]);\n  return null;\n}\n\n/** Mount beside the official conversation without replacing Chat or Composer. */\nfunction SessionWorkbenchBridge({ sessionId, useSession, useSessions, useProjection, useChat, useStore, actions, sendProductionPrompt, cancelProduction, removeQueuedProduction }: WorkbenchSlotProps) {\n  const marker = useRef<HTMLSpanElement>(null);\n  const [target, setTarget] = useState<HTMLElement>();\n  const runningCalls = useChat((snapshot) => snapshot.legacy.runningCalls);\n  const partial = useChat((snapshot) => streamingAssistant(snapshot.timeline));\n  const undispatched = useChat((snapshot) => undispatchedCalls(snapshot), sameUndispatchedCalls);\n  const settledMutation = useChat((snapshot) => latestSettledMutation(snapshot));\n  const settledMutationTurn = useChat((snapshot) => latestSettledMutationTurn(snapshot));\n  const liveTurn = useChat((snapshot) => openTurn(snapshot));\n  const workbench = useStore((memory) => memory.workbench);\n  const gamePane = useStore((memory) => memory.gamePane);\n  const videoPane = useStore((memory) => memory.videoPane);\n  const sessionRunning = useSession((snapshot) => snapshot.running);\n  const inboxRows = useProjection(\"inbox\", (inbox) => inbox?.[\"next-turn\"]);\n  const pendingSubmissions = useSession((snapshot) => snapshot.pendingSubmissions);\n  const productionQueue = useMemo(() => productionQueueFromInbox(\n    inboxRows,\n    new Set(pendingSubmissions.filter((item) => item.placement === \"transcript\").map((item) => item.requestId))\n  ), [inboxRows, pendingSubmissions]);\n  const chat = useChat((snapshot) => snapshot);\n  const productionIntents = useMemo(() => settledProductionIntents(chat), [chat]);\n  const { workspace, error, loading: workspaceLoading, reload } = useWorkspace(sessionId, sessionRunning);\n  const chosenPreference = useStore((memory) => memory.workbenchPreference);\n  const creativeProject = hasCreativeProject(workspace);\n  // DSH 0.1.7 opens a fresh home straight into a blank Session in its default workspace, so\n  // \"no Session yet\" no longer marks a first launch. A blank Session without creative work does.\n  const sessionBlank = useSessions((state) => state.byId[sessionId]?.blank === true);\n  const welcome = sessionBlank && workspace !== undefined && !workspaceLoading && !creativeProject;\n  // The Session Store holds this Session's choice; localStorage carries the workspace's\n  // last choice across restarts. Reading it here keeps the decision in the same render\n  // that learns the workspace, so a collapsed workbench never flashes the layout open.\n  const storedPreference = useMemo(\n    () => readWorkbenchPreference(workbenchPreferenceStorage(), workspace?.cwd),\n    [workspace?.cwd]\n  );\n  const preference = chosenPreference ?? storedPreference;\n  const open = resolveWorkbenchOpen(preference, creativeProject);\n  useLayoutEffect(() => {\n    const document = marker.current?.ownerDocument;\n    if (document === undefined) return;\n    const locate = (): void => {\n      // DSH 0.1.7 renders the same conversation content inside the right sidebar's subagent\n      // chats, so only this Session's main column is a valid seat.\n      const anchor = document.querySelector<HTMLElement>(\n        `[data-conversation-content][data-conversation-session=\"${CSS.escape(sessionId)}\"]:not([data-sidebar-chat] *) > [data-conversation-scroll] > [data-slot='conversation.session']`\n      );\n      setTarget((current) => current === anchor ? current : anchor ?? undefined);\n    };\n    locate();\n    const observer = new MutationObserver(locate);\n    observer.observe(document.body, { childList: true, subtree: true });\n    return () => { observer.disconnect(); };\n  }, [sessionId]);\n  useLayoutEffect(() => {\n    const scroller = target?.parentElement;\n    if (scroller === undefined || scroller === null) return;\n    if (!open) {\n      // A collapsed workbench returns the conversation to DSH untouched, so the only\n      // measurement left is where that column sits: the launcher floats over its corner.\n      const publishSeam = (): void => {\n        const box = scroller.getBoundingClientRect();\n        scroller.style.setProperty(\"--oh-story-seam-top\", `${String(box.top)}px`);\n        scroller.style.setProperty(\"--oh-story-seam-right\", `${String(scroller.ownerDocument.documentElement.clientWidth - box.right)}px`);\n      };\n      publishSeam();\n      const seams = new ResizeObserver(publishSeam);\n      seams.observe(scroller);\n      const view = scroller.ownerDocument.defaultView;\n      view?.addEventListener(\"resize\", publishSeam);\n      return () => {\n        seams.disconnect();\n        view?.removeEventListener(\"resize\", publishSeam);\n        scroller.style.removeProperty(\"--oh-story-seam-top\");\n        scroller.style.removeProperty(\"--oh-story-seam-right\");\n      };\n    }\n    const composerSeat = (): HTMLElement | null => scroller.querySelector(\":scope > [data-composer-seat]\");\n    // The seat overlaps the Chat column here, so a reader parked at the tail has\n    // to be carried across every layout pass; losing the tail does not merely\n    // scroll it out of sight, it leaves the last lines behind the Composer.\n    // Being parked cannot be read inside the pass — a reflow moves the tail\n    // before the observer runs — and it cannot be read from scroll events alone\n    // either: the Chat settles over several frames after a resize and every one\n    // of those frames scrolls without the reader asking. So only a scroll the\n    // reader actually drove releases the tail; reaching the bottom always\n    // reclaims it.\n    const parkedAtTail = (): boolean => scroller.scrollHeight - scroller.scrollTop - scroller.clientHeight <= 8;\n    let parked = parkedAtTail();\n    let drivenAt = 0;\n    const markDriven = (event: Event): void => {\n      if (event.target instanceof Node && composerSeat()?.contains(event.target) === true) return;\n      // A button click (for example switching the editor preview) is not a\n      // scrollbar drag. Its subsequent reflow must not release the Chat tail.\n      if (event.type === \"pointerdown\" && event.target !== scroller) return;\n      drivenAt = performance.now();\n    };\n    const trackParked = (): void => {\n      if (parkedAtTail()) parked = true;\n      else if (performance.now() - drivenAt < 400) parked = false;\n    };\n    const publishLayout = (): void => {\n      scroller.style.setProperty(\"--oh-story-scroll-height\", `${String(scroller.clientHeight)}px`);\n      // DSH 0.1.2 grows the seat with the streaming Todo panel while\n      // --dsh-composer-height keeps reporting the bare input height. Publish the\n      // measurement beside it rather than over it: the CSS takes the larger, so\n      // writing the variable DSH also owns can never turn into a resize duel.\n      scroller.style.setProperty(\"--oh-story-composer-height\", `${String(composerSeat()?.getBoundingClientRect().height ?? 0)}px`);\n      scroller.dataset.ohStoryWorkbench = workbench;\n      const studioPane = workbench === \"video\" ? videoPane : gamePane;\n      scroller.dataset.ohStudioPane = studioPane;\n      const compactAt = workbench === \"game\" || workbench === \"video\" ? 720 : 620;\n      const mediumAt = workbench === \"game\" || workbench === \"video\" ? 960 : 900;\n      const layout = scroller.clientWidth < compactAt ? \"compact\" : scroller.clientWidth < mediumAt ? \"medium\" : \"wide\";\n      if (scroller.dataset.ohStoryLayout !== layout) scroller.dataset.ohStoryLayout = layout;\n      if (parked) scroller.scrollTop = scroller.scrollHeight - scroller.clientHeight;\n    };\n    const observer = new ResizeObserver(publishLayout);\n    const observed = new WeakSet<Element>();\n    // The official seat and Chat flow mount and remount independently of this\n    // bridge. The flow is observed because a resized Chat keeps re-wrapping for\n    // several frames afterwards: pinning once against the height the first frame\n    // reports leaves the reader behind the Composer again once it settles.\n    let flowObserved = false;\n    const observePanes = (): void => {\n      const flow = scroller.querySelector(\"[data-chat-flow]:not([data-step-process-content])\");\n      flowObserved = flow !== null;\n      for (const pane of [composerSeat(), flow]) {\n        if (pane === null || observed.has(pane)) continue;\n        observed.add(pane);\n        observer.observe(pane);\n      }\n    };\n    publishLayout();\n    scroller.addEventListener(\"scroll\", trackParked, { passive: true });\n    for (const driven of [\"wheel\", \"touchmove\", \"pointerdown\", \"keydown\"]) {\n      scroller.addEventListener(driven, markDriven, { passive: true });\n    }\n    observer.observe(scroller);\n    observePanes();\n    const seats = new MutationObserver(() => { observePanes(); publishLayout(); });\n    seats.observe(scroller, { childList: true });\n    // The flow mounts below the seat's level, and streaming mutates it token by\n    // token: watch the subtree only until it has been found once.\n    const panes = new MutationObserver(() => { if (!flowObserved) observePanes(); });\n    panes.observe(scroller, { childList: true, subtree: true });\n    return () => {\n      panes.disconnect();\n      scroller.removeEventListener(\"scroll\", trackParked);\n      for (const driven of [\"wheel\", \"touchmove\", \"pointerdown\", \"keydown\"]) {\n        scroller.removeEventListener(driven, markDriven);\n      }\n      observer.disconnect();\n      seats.disconnect();\n      scroller.style.removeProperty(\"--oh-story-scroll-height\");\n      scroller.style.removeProperty(\"--oh-story-composer-height\");\n      delete scroller.dataset.ohStoryLayout;\n      delete scroller.dataset.ohStoryWorkbench;\n      delete scroller.dataset.ohStudioPane;\n    };\n  }, [gamePane, open, target, videoPane, workbench]);\n  return <>\n    <span ref={marker} className=\"oh-story-bridge-marker\" aria-hidden />\n    {target === undefined ? null : createPortal(<CreativeWorkbench\n      sessionId={sessionId}\n      runningCalls={runningCalls}\n      partial={partial}\n      undispatched={sessionRunning ? undispatched : NO_UNDISPATCHED_CALLS}\n      settledMutation={settledMutation}\n      settledMutationTurn={settledMutationTurn}\n      liveTurn={liveTurn}\n      sessionRunning={sessionRunning}\n      productionQueue={productionQueue}\n      productionIntents={productionIntents}\n      workspace={workspace}\n      error={error}\n      workspaceLoading={workspaceLoading}\n      reload={reload}\n      open={open}\n      creativeProject={creativeProject}\n      welcome={welcome}\n      sendProductionPrompt={sendProductionPrompt}\n      cancelProduction={cancelProduction}\n      removeQueuedProduction={removeQueuedProduction}\n      useStore={useStore}\n      actions={actions}\n    />, target)}\n  </>;\n}\n\ntype WorkbenchSeatProps = PropsRuntime<\"shell.overlay\"> & PropsRenderSlots<\"oh-story.workspace\">;\n\n/**\n * How to reach the workbench from a DSH that has no creative work open yet. Only a Session can\n * open the workbench, so the bundled example's entry appears when one is supplied.\n */\nfunction WelcomeGuide({ onPlayExample }: { readonly onPlayExample?: (() => void) | undefined }) {\n  return <section className=\"oh-story-welcome\" aria-label=\"Oh Story 使用引导\">\n    <style>{styles}</style>\n    <h2>Oh Story 已加载</h2>\n    <p>直接在下方输入框说你想写什么，比如「写一篇 8000 字的重生复仇短篇」，或输入 <code>/story</code>、<code>/short-drama</code>、<code>/novel-to-game quick</code>、<code>/video-recap</code>。写出第一个创作文件后，小说、短剧、游戏、视频工作台会自动出现。</p>\n    <ol>\n      <li>不选文件夹也能开始：作品会写进 DSH 自动建立的「默认工作区 / Default workspace」。</li>\n      <li>想放进自己的作品文件夹：点击左侧「工作区 / Workspaces」旁的「添加工作区 / Add workspace」，在系统弹出的文件夹窗口里选择，再在下方「选择工作区 / Choose workspace」中选中它。</li>\n      <li>输入框右下角显示模型名就说明已配置好；没有模型时，在「设置 → 模型」填入 API Key。只查看已有作品无需 API Key。</li>\n    </ol>\n    {onPlayExample !== undefined && <div className=\"oh-story-welcome-example\">\n      <button type=\"button\" onClick={onPlayExample}>先玩内置示例《金瓶梅 · 风月总账》</button>\n      <span>随插件附带的完整 ADV 游戏，不用 API Key。内容 18+，进入前会确认年龄。</span>\n    </div>}\n  </section>;\n}\n\n/** Without any Session the session-scoped workbench cannot mount, so the guide mounts on its own. */\nfunction WorkbenchWelcome() {\n  const marker = useRef<HTMLSpanElement>(null);\n  const [target, setTarget] = useState<HTMLElement>();\n  useLayoutEffect(() => {\n    const document = marker.current?.ownerDocument;\n    if (document === undefined) return;\n    const locate = (): void => {\n      const anchor = document.querySelector<HTMLElement>(\"[data-conversation-content]:not([data-sidebar-chat] *) > [data-conversation-scroll]\");\n      setTarget((current) => current === anchor ? current : anchor ?? undefined);\n    };\n    locate();\n    const observer = new MutationObserver(locate);\n    observer.observe(document.body, { childList: true, subtree: true });\n    return () => { observer.disconnect(); };\n  }, []);\n  return <>\n    <span ref={marker} className=\"oh-story-bridge-marker\" aria-hidden />\n    {target === undefined ? null : createPortal(<WelcomeGuide />, target)}\n  </>;\n}\n\nfunction WorkbenchSeat({ SessionProvider, renderSlot }: WorkbenchSeatProps) {\n  return <SessionProvider empty={() => <WorkbenchWelcome />}>{renderSlot(\"oh-story.workspace\", {})}</SessionProvider>;\n}\n\nfunction argsOf(block: ToolCallViewProps[\"block\"]): Record<string, unknown> {\n  const raw = (\"kind\" in block ? block.call?.argsRaw : block.phase === \"start\" ? block.argsRaw : undefined) ?? \"{}\";\n  try {\n    const value = JSON.parse(raw) as unknown;\n    return typeof value === \"object\" && value !== null && !Array.isArray(value) ? value as Record<string, unknown> : {};\n  } catch { return {}; }\n}\n\nfunction resultOf(block: ToolCallViewProps[\"block\"]): string | undefined {\n  if (!(\"kind\" in block)) return undefined;\n  return block.content.map((item) => item.type === \"text\" ? item.text : JSON.stringify(item, null, 2)).join(\"\\n\");\n}\n\nfunction RoleToolView({ block, inspect }: ToolCallViewProps) {\n  const args = argsOf(block);\n  const role = typeof args.role === \"string\" ? args.role : \"story-role\";\n  const output = resultOf(block);\n  const state = !(\"kind\" in block) ? \"running\" : block.isError ? \"error\" : \"done\";\n  return <details className=\"oh-story-role\" data-state={state}>\n    <style>{styles}</style>\n    <summary><span>✦ Role</span><strong>{role}</strong><em>{state === \"running\" ? \"运行中\" : state === \"error\" ? \"失败\" : \"完成\"}</em></summary>\n    {output !== undefined && <pre>{output}</pre>}\n    {inspect !== undefined && <button type=\"button\" onClick={inspect}>在轨迹中检查</button>}\n  </details>;\n}\n\nfunction ProductionToolView({ block, inspect }: ToolCallViewProps) {\n  const args = argsOf(block);\n  const action = typeof args.action === \"string\" ? args.action : \"production\";\n  const episode = typeof args.episode === \"string\" ? args.episode : \"短剧\";\n  const state = !(\"kind\" in block) ? \"running\" : block.isError ? \"error\" : \"done\";\n  return <details className=\"oh-story-role\" data-state={state}>\n    <style>{styles}</style>\n    <summary><span>▦ 生产</span><strong>{episode} · {action}</strong><em>{state === \"running\" ? \"执行中\" : state === \"error\" ? \"失败\" : \"已应用\"}</em></summary>\n    {resultOf(block) !== undefined && <pre>{resultOf(block)}</pre>}\n    {inspect !== undefined && <button type=\"button\" onClick={inspect}>在轨迹中检查</button>}\n  </details>;\n}\n\n/** Register only official DSH surfaces; the split bridge never replaces Chat. */\nexport function apply(context: ClientContext): void {\n  context.slots.inject(\"shell.overlay\", () => {\n    const disposeSeat = context.slots.register({\n      name: \"shell.overlay\",\n      id: \"oh-story-workspace\",\n      order: -100,\n      children: { \"oh-story.workspace\": { kind: \"single\", scope: \"session\" } }\n    }, WorkbenchSeat);\n    const disposeWorkbench = context.slots.register({\n      name: \"oh-story.workspace\",\n      store: createWorkbenchStore,\n      inject: (sessionId) => {\n        const binding = (context.sessions as unknown as ISessions).binding(sessionId);\n        const conversation = binding?.ctx.get(\"conversation\");\n        if (binding === undefined || conversation === undefined) {\n          return {\n            sendProductionPrompt: () => Promise.reject(new Error(\"DSH 会话当前不可用。\")),\n            cancelProduction: () => Promise.reject(new Error(\"DSH 会话当前不可用。\")),\n            removeQueuedProduction: () => Promise.reject(new Error(\"DSH 会话当前不可用。\"))\n          };\n        }\n        return {\n          sendProductionPrompt: (prompt: string) => conversation.send(prompt),\n          cancelProduction: () => conversation.cancel(),\n          removeQueuedProduction: (itemId: string) => conversation.updateQueue(itemId as Parameters<IConversation[\"updateQueue\"]>[0], { kind: \"remove\" })\n        };\n      }\n    }, CreativeSplitBridge);\n    return [disposeSeat, disposeWorkbench];\n  });\n  context.slots.inject(\"tool.call.toolview\", () => context.slots.register({\n    name: \"tool.call.toolview\",\n    key: \"oh_story_role\"\n  }, RoleToolView));\n  context.slots.inject(\"tool.call.toolview\", () => context.slots.register({\n    name: \"tool.call.toolview\",\n    key: OH_STORY_PRODUCTION_TOOL_NAME\n  }, ProductionToolView));\n}\n\nexport default { name, inject, apply };\n"
    },
    {
      "path": "packages/dsh-plugin/src/production-tool.ts",
      "content": "import type { Context } from \"@deepseek-ai/cordis\";\nimport { defineTool, type ToolDefinition } from \"@deepseek-ai/dsh-tools\";\nimport {\n  OH_STORY_PRODUCTION_TOOL_NAME,\n  PRODUCTION_INTENT_ACTIONS,\n  PRODUCTION_INTENT_JOB_KINDS,\n  PRODUCTION_INTENT_SECTIONS,\n  validateProductionIntent,\n  type ProductionIntentArgs\n} from \"./production-intent.js\";\n\nfunction intentMessage(intent: ProductionIntentArgs): string {\n  if (intent.action === \"track_job\") return `已把 ${intent.targetId ?? \"生产对象\"} 的 ${intent.jobKind ?? \"媒体\"} 任务投影到 ${intent.episode} 的任务板。`;\n  if (intent.action === \"set_sequence\") return `已把 ${String(intent.shotIds?.length ?? 0)} 个镜头的顺序发送到 ${intent.episode} 成片视图。`;\n  if (intent.action === \"focus_target\") return `已请求 ${intent.episode} 生产视图聚焦 ${intent.targetId ?? \"目标\"}。`;\n  return `已把 ${intent.action} 界面意图发送到 ${intent.episode} 生产工作台。`;\n}\n\nexport function createOhStoryProductionTool(): ToolDefinition {\n  return defineTool({\n    name: OH_STORY_PRODUCTION_TOOL_NAME,\n    description: \"Operate the native oh-story short-drama production projection in the current DSH Session. It can open or focus semantic production targets, set an explicit shot order, or track a job the Agent is actually executing. It never controls cosmetic canvas layout, generates media, changes creator documents, or counts as creator confirmation for paid production.\",\n    parameters: {\n      action: { type: \"string\", required: true, enum: PRODUCTION_INTENT_ACTIONS, description: \"The exact production UI/task projection operation.\" },\n      episode: { type: \"string\", required: true, description: \"Creator-first episode directory, for example 剧集/EP001.\" },\n      section: { type: \"string\", enum: PRODUCTION_INTENT_SECTIONS },\n      targetId: { type: \"string\" },\n      shotIds: { type: \"array\", items: { type: \"string\" } },\n      jobId: { type: \"string\", description: \"Stable ID that must also appear in produced output filenames.\" },\n      jobKind: { type: \"string\", enum: PRODUCTION_INTENT_JOB_KINDS },\n      expectedOutputs: { type: \"integer\", description: \"Number of media files this job will produce. Repeat the count the creator approved when re-registering a batch; omit it to keep the count the workbench already recorded.\" },\n      prompt: { type: \"string\", description: \"Exact prompt/specification for a tracked job; not a production authorization.\" }\n    },\n    output: {\n      schema: {\n        type: \"object\",\n        additionalProperties: false,\n        properties: {\n          action: { type: \"string\", required: true, enum: PRODUCTION_INTENT_ACTIONS },\n          episode: { type: \"string\", required: true },\n          message: { type: \"string\", required: true }\n        }\n      },\n      render: (_args, value) => [{ type: \"text\", text: value.message }]\n    },\n    isConcurrencySafe: () => true,\n    execute(args) {\n      const intent = validateProductionIntent(args);\n      return Promise.resolve({ action: intent.action, episode: intent.episode, message: intentMessage(intent) });\n    }\n  });\n}\n\nexport function registerOhStoryProductionTool(context: Context): void {\n  context.tools.register(createOhStoryProductionTool());\n}\n"
    },
    {
      "path": "packages/dsh-plugin/src/client/production-runtime.ts",
      "content": "export type ProductionJobKind = \"image\" | \"video\" | \"composition\";\nexport type ProductionJobStatus = \"awaiting_confirmation\" | \"pending\" | \"running\" | \"dispatched_unknown\" | \"succeeded\" | \"failed\" | \"canceled\";\n\nexport interface ProductionMediaVersion {\n  readonly id: string;\n  readonly targetId: string;\n  readonly kind: \"image\" | \"video\";\n  readonly url: string;\n  /** Workspace-relative path when the result is owned by the DSH FileSystem. */\n  readonly path?: string | undefined;\n}\n\nexport interface ProductionJob {\n  readonly id: string;\n  readonly targetId: string;\n  readonly kind: ProductionJobKind;\n  readonly status: ProductionJobStatus;\n  readonly progress: number;\n  readonly prompt: string;\n  readonly error?: string | undefined;\n  readonly output?: ProductionMediaVersion | undefined;\n  readonly expectedOutputs: number;\n  readonly completedOutputs: number;\n  /**\n   * Deliverable whose name the job cannot influence. Drama Skills 0.7 renders the\n   * assembled cut to a fixed path, so it carries no job id to correlate on.\n   */\n  readonly outputPath?: string | undefined;\n  /** Versions already at `outputPath` when the job was dispatched, so an earlier cut never completes it. */\n  readonly supersededOutputIds?: readonly string[] | undefined;\n}\n\nexport interface ProductionSequenceItem {\n  readonly shotId: string;\n  /** Creator-chosen source for this cut; absent keeps automatic video-first resolution. */\n  readonly sourceVersionId?: string | undefined;\n  /** Resolved source used for preview and composition; recomputed as media changes. */\n  readonly versionId?: string | undefined;\n}\n\nexport interface CanvasPoint {\n  readonly x: number;\n  readonly y: number;\n}\n\nexport interface ProductionQueueEntry {\n  readonly id: string;\n  readonly preview: string;\n}\n\nfunction record(value: unknown): Record<string, unknown> | undefined {\n  return typeof value === \"object\" && value !== null && !Array.isArray(value) ? value as Record<string, unknown> : undefined;\n}\n\n/**\n * DSH Queue rows from the host `inbox` projection's `next-turn` list. DSH 0.1.7 removed\n * `SessionSnapshot.queue`; reading it threw and blanked the whole workbench (#50). The\n * projection is wire JSON and absent without agent-loop, so every row is checked rather than\n * trusted. Like DSH's own QueueDock, a row whose prompt RPC already has a transcript echo is\n * a turn being claimed, not a queued one. The preview is the row's full text: the job-id label\n * is matched against it, and the old 200-character preview could cut that label off.\n */\nexport function productionQueueFromInbox(rows: unknown, claimedRequestIds: ReadonlySet<string> = new Set()): ProductionQueueEntry[] {\n  if (!Array.isArray(rows)) return [];\n  return rows.flatMap((row) => {\n    const item = record(row);\n    if (item === undefined || typeof item.id !== \"string\" || !Array.isArray(item.content)) return [];\n    const source = record(item.source);\n    if (source?.kind === \"user\" && typeof source.rpcId === \"string\" && claimedRequestIds.has(source.rpcId)) return [];\n    const preview = item.content.flatMap((block) => {\n      const value = record(block);\n      return value?.type === \"text\" && typeof value.text === \"string\" ? [value.text] : [];\n    }).join(\" \");\n    return [{ id: item.id, preview }];\n  });\n}\n\nexport function createPendingJob(input: {\n  readonly id: string;\n  readonly targetId: string;\n  readonly kind: ProductionJobKind;\n  readonly prompt: string;\n  readonly expectedOutputs?: number | undefined;\n  readonly outputPath?: string | undefined;\n  readonly supersededOutputIds?: readonly string[] | undefined;\n}): ProductionJob {\n  return {\n    id: input.id,\n    targetId: input.targetId,\n    kind: input.kind,\n    status: \"pending\",\n    progress: 0,\n    prompt: input.prompt,\n    expectedOutputs: Math.max(1, Math.floor(input.expectedOutputs ?? 1)),\n    completedOutputs: 0,\n    outputPath: input.outputPath,\n    supersededOutputIds: input.supersededOutputIds\n  };\n}\n\nexport function selectedVersionForTarget(\n  targetId: string,\n  versions: readonly ProductionMediaVersion[],\n  selections: Readonly<Record<string, string>>,\n  kind?: ProductionMediaVersion[\"kind\"]\n): ProductionMediaVersion | undefined {\n  const candidates = versions.filter((version) => version.targetId === targetId && (kind === undefined || version.kind === kind));\n  return candidates.find((version) => version.id === selections[targetId]) ?? candidates.at(-1);\n}\n\n/**\n * Upstream's edit stage owns what it writes under 制作成果/成片/ — the cut, its segments, and clips\n * normalised into 成片/规格统一/ — so none of it is a new version of a shot or asset, even when a\n * filename carries that shot's or MOTION's ID.\n */\nconst EDIT_OUTPUT_DIRECTORY = /(?:^|\\/)制作成果\\/成片\\//u;\n\nexport function mediaTargetFromPath(path: string, knownTargets: readonly string[]): string | undefined {\n  if (EDIT_OUTPUT_DIRECTORY.test(path)) return undefined;\n  const upper = path.toLocaleUpperCase();\n  const segments = upper.split(\"/\");\n  const filename = segments.at(-1) ?? \"\";\n  return [...knownTargets].sort((left, right) => right.length - left.length).find((target) => {\n    const canonical = target.toLocaleUpperCase();\n    return segments.includes(canonical)\n      || filename === canonical\n      || filename.startsWith(`${canonical}.`)\n      || filename.startsWith(`${canonical}-`);\n  });\n}\n\nexport function mediaVersionMatchesJob(version: ProductionMediaVersion, jobId: string): boolean {\n  if (version.path === undefined || jobId.trim() === \"\") return false;\n  const escaped = jobId.replace(/[.*+?^${}()|[\\]\\\\]/gu, \"\\\\$&\");\n  const basename = version.path.split(\"/\").at(-1) ?? \"\";\n  return new RegExp(`(?:^|[-_.])${escaped}(?:[-_.]|$)`, \"u\").test(basename);\n}\n\nexport function outputsForJob(job: ProductionJob, versions: readonly ProductionMediaVersion[]): ProductionMediaVersion[] {\n  if (job.outputPath === undefined) return versions.filter((version) => mediaVersionMatchesJob(version, job.id));\n  const superseded = new Set(job.supersededOutputIds ?? []);\n  return versions.filter((version) => version.path === job.outputPath && !superseded.has(version.id));\n}\n\n/**\n * True while a composition the creator already dispatched has not settled. Every composition\n * for an episode renders to the same upstream path, so a second one dispatched now would be\n * completed by the first one's cut — and, once marked succeeded, could no longer be removed\n * from the DSH Queue.\n */\nexport function compositionInFlight(jobs: readonly ProductionJob[]): boolean {\n  return jobs.some((job) => job.kind === \"composition\"\n    && (job.status === \"awaiting_confirmation\" || job.status === \"pending\" || job.status === \"running\"));\n}\n\n/**\n * A composition whose Turn ended without a cut stays dispatched_unknown so a late cut can still\n * complete it, and compositionInFlight lets the creator compose again. Both render to the same\n * upstream path, so once a new composition is dispatched its cut would complete the old job too.\n * Fail the old one instead, keeping the check findings its error already reports.\n */\nexport function settleSupersededCompositions(jobs: readonly ProductionJob[], next: ProductionJob): ProductionJob[] {\n  if (next.kind !== \"composition\") return [...jobs];\n  return jobs.map((job) => (\n    job.id !== next.id\n    && job.kind === \"composition\"\n    && job.status === \"dispatched_unknown\"\n    && (job.targetId === next.targetId || (job.outputPath !== undefined && job.outputPath === next.outputPath))\n      ? { ...job, status: \"failed\" }\n      : job\n  ));\n}\n\nexport function referencesForTarget(\n  targetId: string,\n  production: { readonly shots: readonly { readonly id: string; readonly references: readonly string[] }[] },\n  versions: readonly ProductionMediaVersion[],\n  selections: Readonly<Record<string, string>>,\n  libraryVersions: readonly ProductionMediaVersion[] = versions,\n  manualReferences: Readonly<Record<string, readonly string[]>> = {}\n): ProductionMediaVersion[] {\n  const shot = production.shots.find((item) => item.id === targetId);\n  if (shot === undefined) return [];\n  const declared = shot.references.flatMap((id) => {\n    const version = selectedVersionForTarget(id, versions, selections, \"image\");\n    return version === undefined ? [] : [version];\n  });\n  const manual = (manualReferences[targetId] ?? []).flatMap((id) => {\n    const version = libraryVersions.find((item) => item.id === id && item.kind === \"image\");\n    return version === undefined ? [] : [version];\n  });\n  return [...new Map([...declared, ...manual].map((version) => [version.id, version])).values()];\n}\n\nexport function mediaBelongsToEpisode(path: string | undefined, episodeDirectory: string): boolean {\n  if (path === undefined) return true;\n  if (path.startsWith(`${episodeDirectory}/`)) return true;\n  const episodeName = episodeDirectory.split(\"/\").at(-1);\n  return episodeName !== undefined && path.startsWith(`交付/${episodeName}/`);\n}\n\nexport function sequenceSourceEligible(shotId: string, version: ProductionMediaVersion): boolean {\n  return version.kind === \"video\"\n    ? version.targetId === shotId\n    : version.targetId === shotId || version.targetId.startsWith(\"IMG-\");\n}\n\nexport function queuedItemForJob(jobId: string, queue: readonly ProductionQueueEntry[]): ProductionQueueEntry | undefined {\n  if (jobId.trim() === \"\") return undefined;\n  const escaped = jobId.replace(/[.*+?^${}()|[\\]\\\\]/gu, \"\\\\$&\");\n  // The prompts label the id as 「任务 ID：<id>」 / 「批次任务 ID：<id>」. Anchor on that label so an\n  // id merely quoted inside another job's output paths cannot mark this job as queued.\n  const labelled = new RegExp(`任务\\\\s*ID\\\\s*[：:]\\\\s*${escaped}(?:[\\\\s.,;、。]|$)`, \"u\");\n  return queue.find((item) => labelled.test(item.preview));\n}\n\nexport function activeProductionJobId(\n  jobs: readonly ProductionJob[],\n  queue: readonly ProductionQueueEntry[],\n  sessionRunning: boolean\n): string | undefined {\n  if (!sessionRunning) return undefined;\n  return [...jobs].reverse().find((job) => (\n    (job.status === \"awaiting_confirmation\" || job.status === \"pending\" || job.status === \"running\")\n    && queuedItemForJob(job.id, queue) === undefined\n  ))?.id;\n}\n\n/** Reconcile the lightweight Session projection against DSH Queue/Turn state and real workspace outputs. */\nexport function reconcileProductionJobs(\n  jobs: readonly ProductionJob[],\n  queue: readonly ProductionQueueEntry[],\n  sessionRunning: boolean,\n  versions: readonly ProductionMediaVersion[]\n): ProductionJob[] {\n  const latestPending = [...jobs].reverse().find((job) => (\n    job.status === \"pending\" && queuedItemForJob(job.id, queue) === undefined\n  ));\n\n  // Retire an unfinished composition only once a newer one actually runs, and before outputs are\n  // matched, so the newer cut cannot complete it. A dispatch that fails or is withdrawn from the\n  // Queue leaves the older one to be finished in Chat.\n  const settleCompositions = (list: readonly ProductionJob[]): ProductionJob[] => list\n    .filter((job) => job.kind === \"composition\" && job.status === \"running\")\n    .reduce((current, running) => settleSupersededCompositions(current, running), [...list]);\n  const reconciled = settleCompositions(jobs).map((job): ProductionJob => {\n    const queued = queuedItemForJob(job.id, queue) !== undefined;\n    // A terminal job is never revived by a result that arrived later. This matters most for\n    // `outputPath`: a shared deliverable name carries no job identity, so without this guard\n    // the next cut would complete a job the creator canceled, and bury the error a failed one\n    // reported. A job-id correlated failure keeps its old behaviour — that output really is its own.\n    if (job.status === \"canceled\" || job.status === \"succeeded\") return job;\n    if (job.status === \"failed\" && job.outputPath !== undefined) return job;\n    const outputs = outputsForJob(job, versions);\n\n    if (outputs.length >= job.expectedOutputs) {\n      return {\n        ...job,\n        status: \"succeeded\",\n        progress: 100,\n        completedOutputs: outputs.length,\n        output: outputs[0],\n        error: undefined\n      };\n    }\n    if (job.status === \"awaiting_confirmation\" && outputs.length === 0) return job;\n    if (job.status === \"running\" && queued) return { ...job, status: \"pending\", progress: 0 };\n    if (job.status === \"pending\" && sessionRunning && !queued && job === latestPending) {\n      return { ...job, status: \"running\", progress: Math.max(10, job.progress), error: undefined };\n    }\n    if (!sessionRunning && !queued && (job.status === \"running\" || job.status === \"dispatched_unknown\")) {\n      return {\n        ...job,\n        status: \"dispatched_unknown\",\n        progress: Math.round(outputs.length / job.expectedOutputs * 100),\n        completedOutputs: outputs.length,\n        // Assembly is local ffmpeg, so nothing was billed: a missing cut usually means edit_tool\n        // check blocked the render, and those findings — not a billing warning — are what to show.\n        error: outputs.length > 0\n          ? `DSH Turn 已结束，已发现 ${String(outputs.length)}/${String(job.expectedOutputs)} 项成果；请刷新核对剩余输出。`\n          : job.kind === \"composition\"\n            ? \"成片未生成：请在 Chat 查看 edit_tool check 的阻断项（未采用镜头理由、画幅/帧率不一致等），修正后再合成。\"\n            : \"DSH Turn 已结束，尚未发现关联成果。任务可能已派发，请先刷新成果，避免重复计费。\"\n      };\n    }\n    if (outputs.length > 0) {\n      return {\n        ...job,\n        status: job.status === \"failed\" ? \"failed\" : \"running\",\n        progress: Math.max(10, Math.round(outputs.length / job.expectedOutputs * 100)),\n        completedOutputs: outputs.length,\n        error: job.status === \"failed\" ? job.error : undefined\n      };\n    }\n    return job;\n  });\n  return settleCompositions(reconciled);\n}\n\nexport function reconcileSequence(\n  shotIds: readonly string[],\n  current: readonly ProductionSequenceItem[],\n  versions: readonly ProductionMediaVersion[],\n  selections: Readonly<Record<string, string>>,\n  episodeDirectory?: string\n): ProductionSequenceItem[] {\n  const scopedVersions = episodeDirectory === undefined\n    ? versions\n    : versions.filter((version) => mediaBelongsToEpisode(version.path, episodeDirectory));\n  const shotSet = new Set(shotIds);\n  const preserved = current.filter((item) => shotSet.has(item.shotId));\n  const present = new Set(preserved.map((item) => item.shotId));\n  const appended: ProductionSequenceItem[] = shotIds.filter((shotId) => !present.has(shotId)).map((shotId) => ({ shotId }));\n  return [...preserved, ...appended].map((item) => {\n    if (item.sourceVersionId !== undefined) {\n      const explicit = scopedVersions.find((version) => version.id === item.sourceVersionId && sequenceSourceEligible(item.shotId, version));\n      return { ...item, versionId: explicit?.id };\n    }\n    // A produced video remains the preferred cut source even when the version strip currently\n    // points at its earlier keyframe. Static assembly is the fallback: use an explicitly selected\n    // SHOT/IMG image first, otherwise the current shot's accepted keyframe. Never pull an image\n    // from another target merely because it happened to arrive last.\n    const video = selectedVersionForTarget(item.shotId, scopedVersions, selections, \"video\");\n    const selectedImageId = selections[item.shotId];\n    const selectedImage = selectedImageId === undefined ? undefined : scopedVersions.find((version) => (\n      version.id === selectedImageId\n      && version.kind === \"image\"\n      && (version.targetId === item.shotId || version.targetId.startsWith(\"IMG-\"))\n    ));\n    const shotImage = selectedVersionForTarget(item.shotId, scopedVersions, selections, \"image\");\n    const preservedImage = scopedVersions.find((version) => (\n      version.id === item.versionId && version.kind === \"image\" && version.targetId.startsWith(\"IMG-\")\n    ));\n    const image = selectedImage ?? shotImage ?? preservedImage;\n    return { shotId: item.shotId, versionId: video?.id ?? image?.id };\n  });\n}\n\nexport function sequenceIssues(sequence: readonly ProductionSequenceItem[], versions: readonly ProductionMediaVersion[], episodeDirectory?: string): string[] {\n  const versionById = new Map(versions\n    .filter((version) => episodeDirectory === undefined || mediaBelongsToEpisode(version.path, episodeDirectory))\n    .map((version) => [version.id, version]));\n  const issues: string[] = [];\n  for (const item of sequence) {\n    const version = item.versionId === undefined ? undefined : versionById.get(item.versionId);\n    if (version === undefined || (version.kind !== \"video\" && version.kind !== \"image\")) {\n      issues.push(item.sourceVersionId === undefined\n        ? `${item.shotId} 缺少已选视频或关键帧素材`\n        : `${item.shotId} 显式选择的成片素材已不可用`);\n    }\n    else if (version.path === undefined) issues.push(`${item.shotId} 的${version.kind === \"video\" ? \"视频\" : \"关键帧\"}没有可供 DSH 读取的工作区路径`);\n  }\n  return issues;\n}\n\nexport function reorderSequence(sequence: readonly ProductionSequenceItem[], source: number, target: number): ProductionSequenceItem[] {\n  if (!Number.isInteger(source) || !Number.isInteger(target)) return [...sequence];\n  if (source < 0 || target < 0 || source >= sequence.length || target >= sequence.length || source === target) return [...sequence];\n  const next = [...sequence];\n  const [item] = next.splice(source, 1);\n  if (item !== undefined) next.splice(target, 0, item);\n  return next;\n}\n"
